/* Bid Dictionary: plain-language definitions of words, abbreviations and phrases found in commercial landscape, irrigation and planting bids (San Diego County). Examples cite real Caltrans District 11 and City of San Diego bid documents used in this course. */
window.GLOSSARY = [
  {"term":"(E) Existing","abbr":"(E)","also":"EXIST; Exist; EX","cat":"Plans & drawings","def":"Marks something already on the site. It stays unless the plans say remove, relocate or modify it.","ex":"Caltrans plans write “Exist,” as in “Exist AC Dike.”","mod":4},
  {"term":"(F) Final pay item","abbr":"(F)","also":"final pay quantity","cat":"Bidding & contracts","def":"Caltrans mark on a bid item meaning you're paid the bid quantity, not the measured quantity, unless the Engineer changes the work. Check these quantities hardest.","ex":"Caltrans 11-428704: item 25 (iceplant cuttings) and items 57 to 63 (supply pipe) were (F) items.","mod":15},
  {"term":"(Mod) Modified","abbr":"(Mod)","also":"Mod","cat":"Plans & drawings","def":"Marks a standard detail or item changed for this job. Read what changed.","ex":"Caltrans 11-428704: “HMA Dike (Type E Mod).”","mod":4},
  {"term":"(N) Not a separate pay item","abbr":"(N)","cat":"Plans & drawings","def":"On Caltrans plans, marks work that has no bid item of its own. You still must do it, so put its cost into a related item. On other plans, (N) may simply mean “new,” so check the legend.","mod":6},
  {"term":"@","abbr":"@","also":"at","cat":"Plans & drawings","def":"Means “at” on plans, like “#4 @ 12\"” for rebar spaced 12 inches apart, or “trees @ 20' O.C.”","mod":4},
  {"term":"1-gallon container","abbr":"1 GAL","also":"#1; No. 1 container; one-gallon","cat":"Planting & soil","def":"The most common small nursery container for shrubs and groundcovers. Caltrans calls this Plant Group A.","ex":"Caltrans 11-428704 item 27: Plant (Group A), 1,460 EA.","mod":7},
  {"term":"2/10 net 30","abbr":"","also":"early pay discount","cat":"Money & estimating","def":"Supplier terms: take 2% off if you pay within 10 days, or pay the full amount in 30.","mod":8},
  {"term":"5-gallon container","abbr":"5 GAL","also":"#5; No. 5 container","cat":"Planting & soil","def":"A mid-size nursery container for shrubs and small trees. Caltrans calls this Plant Group B.","ex":"Caltrans 11-428704 item 28: Plant (Group B), 110 EA (ghost aloe).","mod":7},
  {"term":"15-gallon container","abbr":"15 GAL","also":"#15; No. 15 container","cat":"Planting & soil","def":"A larger nursery container, common for young trees and big shrubs. Caltrans calls this Plant Group U.","ex":"Caltrans 11-430674 item 39: Plant (Group U), 960 EA.","mod":7},
  {"term":"24-inch box","abbr":"24\" BOX","also":"24\" box tree","cat":"Planting & soil","def":"A wooden box 24 inches across, used for trees. Heavy: needs equipment to set. Caltrans calls this Plant Group K.","ex":"Caltrans 11-428704 item 26: Plant (Group K), 43 EA (pines).","mod":7},
  {"term":"36-inch box","abbr":"36\" BOX","cat":"Planting & soil","def":"A larger boxed tree, 36 inches across. Needs a machine and more crew to plant.","mod":7},
  {"term":"48-inch box","abbr":"48\" BOX","cat":"Planting & soil","def":"A large specimen boxed tree, 48 inches across. Often needs a crane or large loader and a long lead time.","mod":7},
  {"term":"324 (cubic yard divisor)","abbr":"","cat":"Units & measurement","def":"Area in SF times depth in inches, divided by 324, gives cubic yards. 324 = 27 × 12.","ex":"Example: 5,000 SF of mulch 3 inches deep: 5,000 × 3 ÷ 324 = 46.3 CY.","mod":0},
  {"term":"A license","abbr":"A","also":"Class A; General Engineering Contractor","cat":"Licensing, insurance & bonds","def":"California's general engineering license, for fixed works like roads, pipelines, grading and parks. Caltrans landscape jobs often accept Class A or the right Class C licenses.","ex":"Caltrans 11-422004 required “Class A, or a combination of Class C licenses that makes up the majority of the work.”","mod":2},
  {"term":"Abandon in place","abbr":"AIP","cat":"Plans & drawings","def":"Leave an old pipe or line in the ground, cut and capped, instead of digging it out.","mod":4},
  {"term":"Accounts payable","abbr":"AP","also":"payables","cat":"Money & estimating","def":"Money your company owes suppliers and subs.","mod":16},
  {"term":"Accounts receivable","abbr":"AR","also":"receivables","cat":"Money & estimating","def":"Money owed to your company for work billed. Retention is part of it.","mod":16},
  {"term":"Acknowledge an addendum","abbr":"","cat":"Bidding & contracts","def":"To show on your bid that you received and priced an addendum, usually by writing its number and date on the bid form. Missing one can get a public bid thrown out.","ex":"Example: “Addenda received: No. 1 dated 8/20, No. 2 dated 8/27.”","mod":12},
  {"term":"ACORD 25","abbr":"","cat":"Licensing, insurance & bonds","def":"The standard certificate of liability insurance form brokers use for COIs.","mod":2},
  {"term":"Acre","abbr":"AC","also":"ac","cat":"Units & measurement","def":"A land area of 43,560 square feet.","mod":0},
  {"term":"Addendum","abbr":"","also":"addenda (plural); bulletin","cat":"Bidding & contracts","def":"An official change to the bid documents, issued before bids are due. Every addendum becomes part of the contract, so you must price it.","ex":"On Caltrans 11-428704, Addendum 1 changed item 25 (iceplant cuttings) from 60,015 to 61,975 EA.","mod":12},
  {"term":"Addendum log","abbr":"","cat":"Bidding & contracts","def":"Your own list of every addendum: what it changed and whether your takeoff and price were updated.","mod":12},
  {"term":"Additional insured","abbr":"AI","cat":"Licensing, insurance & bonds","def":"A policy endorsement that extends your liability insurance to protect the GC, owner and others named in the contract.","mod":2},
  {"term":"Additional insured endorsement","abbr":"","also":"AI endorsement","cat":"Licensing, insurance & bonds","def":"The actual policy page that adds others as additional insureds. Contracts often name forms like CG 20 10 (ongoing work) and CG 20 37 (completed work).","mod":2},
  {"term":"Additive alternate","abbr":"","also":"add alternate; add alt","cat":"Bidding & contracts","def":"Extra work priced separately from the base bid. The owner may choose to add it after seeing prices.","ex":"Example: “Add Alternate 1: upsize all trees on the north slope from 15 GAL to 24-inch box.”","mod":14},
  {"term":"Adjustment factor","abbr":"","also":"difficulty factor","cat":"Money & estimating","def":"A multiplier on a production rate for harder conditions, like steep slopes, rocky soil or night work.","mod":9},
  {"term":"Admitted surety","abbr":"","cat":"Licensing, insurance & bonds","def":"A surety company licensed by the California Department of Insurance to issue bonds in the state.","mod":2},
  {"term":"Aerially deposited lead","abbr":"ADL","cat":"Public works & compliance","def":"Lead from old car exhaust that settled in soil along freeways. Caltrans jobs that dig this soil require special handling and a lead compliance plan.","ex":"Caltrans 11-428804 item 28: Roadway Excavation (Type Z-2) (Aerially Deposited Lead), 470 CY.","mod":15},
  {"term":"Aggregate base","abbr":"AB","also":"base; base rock","cat":"Hardscape & site work","def":"Crushed rock placed and compacted under paving and walks. California specs call the common grade Class 2 aggregate base.","ex":"Caltrans 11-422004 item 44: Class 2 Aggregate Base (CY), 40 CY.","mod":7},
  {"term":"Aggregate bonding limit","abbr":"","also":"aggregate program","cat":"Licensing, insurance & bonds","def":"The total amount of bonded work you can have going at one time.","mod":2},
  {"term":"Aggregate limit","abbr":"","also":"general aggregate","cat":"Licensing, insurance & bonds","def":"The most a policy pays in total during the policy year. Some contracts require a separate aggregate for each project.","mod":2},
  {"term":"Agronomic soil test","abbr":"","also":"soil fertility test","cat":"Planting & soil","def":"A lab test of soil fertility and chemistry that comes with recommended amendment and fertilizer rates.","mod":5},
  {"term":"Air release valve","abbr":"ARV","also":"air relief valve","cat":"Irrigation","def":"A valve on high points of a mainline that lets trapped air out, which protects pipe from surges.","mod":6},
  {"term":"Allowance","abbr":"","cat":"Bidding & contracts","def":"A set dollar amount the owner tells every bidder to include for something not fully known yet. You carry exactly that amount. Money not used goes back to the owner.","ex":"Example: “Include an allowance of $10,000 for repairs to existing irrigation.”","mod":13},
  {"term":"Alternate","abbr":"ALT","also":"bid alternate","cat":"Bidding & contracts","def":"An option priced separately from the base bid, either as an add or a deduct.","mod":13},
  {"term":"American Society for Testing and Materials","abbr":"ASTM","also":"ASTM International","cat":"Agencies & organizations","def":"The group that writes test methods and material standards. Specs cite them, like ASTM D1785 for Schedule 40 PVC pipe.","mod":5},
  {"term":"American Water Works Association","abbr":"AWWA","cat":"Agencies & organizations","def":"The group that writes standards for water pipe and fittings, like AWWA C900 PVC pipe. Its California-Nevada Section certifies backflow testers.","mod":6},
  {"term":"American Wire Gauge","abbr":"AWG","also":"gauge","cat":"Units & measurement","def":"The wire size system. Lower numbers are thicker wire: 12 AWG is thicker than 14 AWG.","mod":6},
  {"term":"Americans with Disabilities Act","abbr":"ADA","cat":"Public works & compliance","def":"The federal law requiring access for people with disabilities. For your work it sets rules for walks, ramps, slopes and clear paths. California adds its own access rules in the building code.","mod":7},
  {"term":"Amp","abbr":"A","also":"ampere","cat":"Units & measurement","def":"The unit of electrical current. Breakers and wire are sized by amps.","mod":6},
  {"term":"Annual color","abbr":"","also":"color; bedding plants","cat":"Planting & soil","def":"Seasonal flowering plants replaced each season. Common on maintenance contracts.","mod":7},
  {"term":"Annualization","abbr":"","cat":"Public works & compliance","def":"A prevailing wage rule: credit for benefit payments is spread over all hours the worker works in the year, on public and private jobs.","mod":11},
  {"term":"Antenna mast","abbr":"","cat":"Irrigation","def":"A pole and antenna that lets a controller talk by radio to a central system.","ex":"Caltrans 11-428704 item 47: Antenna Mast, 3 EA.","mod":15},
  {"term":"Anti-drain valve","abbr":"","also":"check valve; low-head drainage valve","cat":"Irrigation","def":"A small valve in a head or riser that stops water from draining out of the low heads after a zone shuts off.","mod":6},
  {"term":"Apparent low bidder","abbr":"","also":"apparent low","cat":"Bidding & contracts","def":"The bidder with the lowest price when bids are opened, before the agency checks the bid. The bid can still be rejected.","ex":"On Caltrans 11-428704 the lowest price, $1,106,287.75, was marked NR for a late DBE/DVBE submittal. The job went to the next bidder at $1,176,120.00.","mod":14},
  {"term":"Apples to apples","abbr":"","cat":"Construction phrases & jargon","def":"Comparing bids that cover exactly the same scope, so the prices can be fairly compared.","mod":13},
  {"term":"Apprentice","abbr":"","cat":"Public works & compliance","def":"A registered trainee in a state-approved apprenticeship program, paid apprentice wage rates.","mod":11},
  {"term":"Apprentice ratio","abbr":"","also":"1 to 5 ratio","cat":"Public works & compliance","def":"On California public works of $30,000 or more, contractors must generally employ at least 1 apprentice hour for every 5 journeyman hours in an apprenticeable craft, on straight time.","mod":11},
  {"term":"Arborist","abbr":"","also":"certified arborist","cat":"Planting & soil","def":"A tree care expert. Specs may require an ISA Certified Arborist for pruning, protection or reports.","mod":7},
  {"term":"Arc","abbr":"","also":"pattern","cat":"Irrigation","def":"How much of a circle a sprinkler covers: quarter (90°), half (180°), full (360°) or adjustable.","mod":6},
  {"term":"Area drain","abbr":"AD","cat":"Hardscape & site work","def":"A small grated drain in a planting or paved area that collects surface water into a pipe.","mod":4},
  {"term":"As directed","abbr":"","also":"as directed by the Engineer","cat":"Specifications","def":"Spec words meaning the work is done when, where and how the owner's representative says. Quantities can be hard to predict, so price carefully.","mod":5},
  {"term":"As required","abbr":"","also":"as needed","cat":"Specifications","def":"Vague spec words that put the risk of quantity on you. State in your proposal what you priced.","mod":5},
  {"term":"As shown","abbr":"","also":"as indicated; as detailed","cat":"Specifications","def":"Spec words meaning “build what the plans show.” Your price must match the drawings.","mod":5},
  {"term":"As-builts","abbr":"","also":"as-built drawings; record drawings","cat":"Plans & drawings","def":"Same as record drawings: plans showing what was actually built, including pipe routes, valve locations and changes.","mod":16},
  {"term":"Asphalt concrete","abbr":"AC","also":"asphalt; blacktop","cat":"Hardscape & site work","def":"Paving made of rock and asphalt binder. Caltrans now calls it hot mix asphalt.","mod":7},
  {"term":"Asphalt dike","abbr":"","also":"AC dike; HMA dike","cat":"Hardscape & site work","def":"A small asphalt curb at the edge of a road that directs water.","ex":"Caltrans 11-428804 item 82: Place Hot Mix Asphalt Dike (Type E Modified), 330 LF.","mod":15},
  {"term":"Assembly","abbr":"","cat":"Money & estimating","def":"A group of parts priced together as one unit, like a valve with its box, fittings and wire splices.","mod":6},
  {"term":"Associated General Contractors","abbr":"AGC","cat":"Agencies & organizations","def":"A national trade group for contractors, with a San Diego chapter. Offers training, networking and contract forms.","mod":3},
  {"term":"Atmospheric vacuum breaker","abbr":"AVB","cat":"Irrigation","def":"The simplest backflow device, installed after each valve and above the highest head. Many agencies don't allow it on commercial work, so check local rules.","mod":6},
  {"term":"Award","abbr":"","also":"contract award","cat":"Bidding & contracts","def":"The owner's decision to give the contract to a bidder. Public agencies usually award to the lowest responsive, responsible bidder.","ex":"Caltrans 11-428704: bids opened 9/8/21; bid summary dated 9/22/21.","mod":16},
  {"term":"Awarding body","abbr":"","also":"awarding agency","cat":"Public works & compliance","def":"The public agency that awards a public works contract, like a city, school district or Caltrans.","mod":11},
  {"term":"B license","abbr":"B","also":"Class B; General Building Contractor","cat":"Licensing, insurance & bonds","def":"California's general building license, for structures for people, animals or property. A B contractor can take a prime contract with two or more unrelated trades, or do framing or carpentry. For a landscape-only prime contract, it must also hold the C-27 or subcontract the work to a C-27 contractor.","mod":2},
  {"term":"B-2 license","abbr":"B-2","also":"Residential Remodeling Contractor","cat":"Licensing, insurance & bonds","def":"A California license for residential remodeling projects only. It doesn't cover commercial landscape work.","mod":2},
  {"term":"Back charge","abbr":"","also":"backcharge","cat":"Bidding & contracts","def":"A cost the GC takes out of your payment for work it says it did for you, like cleanup or repairs. Your subcontract says how the GC must notify you first.","mod":16},
  {"term":"Back of curb","abbr":"BC","also":"BOC","cat":"Plans & drawings","def":"The edge of a curb on the side away from the street, often where planting areas start.","mod":4},
  {"term":"Backfill","abbr":"","cat":"Grading, demo & erosion control","def":"Soil put back into a trench or hole and compacted. Specs may require sand or select fill near pipe.","mod":6},
  {"term":"Backfill mix","abbr":"","also":"planting mix","cat":"Planting & soil","def":"The soil put back around a plant's root ball, often native soil blended with amendment per the specs.","mod":7},
  {"term":"Backflow enclosure","abbr":"","also":"backflow cage","cat":"Irrigation","def":"A locking metal cage or cover that protects a backflow preventer from theft and damage.","mod":6},
  {"term":"Backflow preventer","abbr":"BFP","also":"backflow; BFP assembly","cat":"Irrigation","def":"An assembly that keeps irrigation water from flowing back into the drinking water supply. Required at the POC. Water agencies set the type and testing rules.","ex":"Caltrans 11-430674 item 72: 2\" Backflow Preventer Assembly, 2 EA.","mod":6},
  {"term":"Backflow test","abbr":"","also":"certification","cat":"Irrigation","def":"A test of a backflow assembly by a certified tester, required after installation and usually every year.","ex":"Caltrans 11-422004 item 32: Certify Existing Backflow Preventers, LS.","mod":6},
  {"term":"Balanced site","abbr":"","also":"balance","cat":"Grading, demo & erosion control","def":"A site where the cut equals the fill, so no soil is imported or exported.","mod":7},
  {"term":"Ball valve","abbr":"BV","cat":"Irrigation","def":"A shutoff valve with a ball inside that turns a quarter turn to open or close.","ex":"Caltrans 11-430674 item 90: Ball Valve, 6 EA.","mod":6},
  {"term":"Balled and burlapped","abbr":"B&B","cat":"Planting & soil","def":"A tree or shrub dug from the field with its root ball wrapped in burlap. Caltrans calls this Plant Group C.","mod":7},
  {"term":"Ballpark price","abbr":"","also":"budget number; rough number","cat":"Construction phrases & jargon","def":"A rough price given before the design is done. Mark it clearly as a budget, not a firm bid.","mod":13},
  {"term":"Bank cubic yard","abbr":"BCY","also":"in-place yards","cat":"Units & measurement","def":"Soil measured in the ground before digging.","mod":0},
  {"term":"Bare root","abbr":"BR","cat":"Planting & soil","def":"A plant sold with no soil on its roots, planted while dormant.","mod":7},
  {"term":"Base bid","abbr":"","cat":"Bidding & contracts","def":"The main bid price, without any alternates.","mod":14},
  {"term":"Basic Engineering Estimating System","abbr":"BEES","cat":"Agencies & organizations","def":"The Caltrans computer system used to build and document engineer's estimates for projects.","mod":15},
  {"term":"Basic hourly rate","abbr":"","also":"base rate","cat":"Public works & compliance","def":"The taxable wage part of the prevailing wage rate, before employer payments.","mod":11},
  {"term":"Basis of design","abbr":"","cat":"Specifications","def":"The named product the design is based on. Others may be allowed if they're equal and approved.","mod":5},
  {"term":"Benchmark","abbr":"BM","cat":"Plans & drawings","def":"A point with a known elevation used as the reference for grades on the job.","mod":4},
  {"term":"Best and final offer","abbr":"BAFO","cat":"Construction phrases & jargon","def":"A last price an owner or GC asks for before deciding. Used more in negotiated work and proposals than in sealed public bids.","mod":13},
  {"term":"Best management practice","abbr":"BMP","cat":"Public works & compliance","def":"A method used to keep soil, trash and pollutants out of storm drains, like fiber rolls, inlet protection or a concrete washout.","mod":7},
  {"term":"Bid","abbr":"","also":"proposal; quote; number","cat":"Bidding & contracts","def":"A written offer to do specific work for a specific price.","mod":1},
  {"term":"Bid bond","abbr":"","also":"bid security","cat":"Licensing, insurance & bonds","def":"A bond from a surety sent with a bid. It guarantees you'll sign the contract and give the required bonds if you win. If you back out, the owner can collect up to the bond amount, often 10% of the bid.","ex":"City of San Diego K-24-1952: the bid bond is uploaded as a PDF on PlanetBids at bid time.","mod":2},
  {"term":"Bid date","abbr":"","also":"bid day; due date","cat":"Bidding & contracts","def":"The date and time bids are due. Public agencies do not accept late bids.","ex":"City of San Diego K-24-1952: due 2:00 PM, December 6, 2023.","mod":14},
  {"term":"Bid day sheet","abbr":"","also":"bid day spreadsheet","cat":"Money & estimating","def":"The spreadsheet an estimator uses on bid day to plug in last-minute supplier and sub prices and total the bid.","mod":14},
  {"term":"Bid documents","abbr":"","also":"bid package; bid set","cat":"Bidding & contracts","def":"Everything issued for bidding: the notice, instructions, bid forms, plans, specs and addenda.","mod":1},
  {"term":"Bid Express","abbr":"","cat":"Agencies & organizations","def":"The website Caltrans uses to receive electronic bids.","mod":14},
  {"term":"Bid form","abbr":"","also":"proposal form","cat":"Bidding & contracts","def":"The agency's form where you write your prices and sign. On public work, use it exactly as issued and fill in every blank.","mod":14},
  {"term":"Bid Item List","abbr":"","also":"bid schedule; schedule of bid items","cat":"Bidding & contracts","def":"The numbered list of items, units and quantities you price on a unit price bid.","ex":"Caltrans 11-428704 had 70 items, from item 1 Lead Compliance Plan to item 70 Mobilization.","mod":14},
  {"term":"Bid leveling","abbr":"","also":"scope leveling","cat":"Bidding & contracts","def":"When a GC lines up sub bids side by side, checks that each covers the same scope, and adds plugs for anything missing.","mod":13},
  {"term":"Bid list","abbr":"","also":"invitation list","cat":"Bidding & contracts","def":"A GC's list of subs it invites to bid.","mod":3},
  {"term":"Bid opening","abbr":"","cat":"Bidding & contracts","def":"When sealed bids are opened and read right after the deadline. Many agencies now open bids online or by webcast.","mod":14},
  {"term":"Bid peddling","abbr":"","cat":"Bidding & contracts","def":"When a sub cuts its price after bid day to take work from the sub who was listed. Unfair practice, the flip side of bid shopping.","mod":14},
  {"term":"Bid platform","abbr":"","cat":"Bidding & contracts","def":"A website GCs use to send bid invites, share plans and collect sub bids.","mod":3},
  {"term":"Bid protest","abbr":"","cat":"Bidding & contracts","def":"A written challenge to another bidder's bid or to the award. Agencies set short deadlines and strict rules for protests.","mod":14},
  {"term":"Bid recap sheet","abbr":"","also":"bid summary sheet","cat":"Money & estimating","def":"One page that adds up every layer of your bid: material, labor, equipment, subs, overhead, bonds and profit.","mod":10},
  {"term":"Bid rigging","abbr":"","also":"collusion; cover bidding","cat":"Public works & compliance","def":"When bidders secretly agree on who will win or what they'll bid. It's a crime.","mod":14},
  {"term":"Bid security","abbr":"","also":"bid guarantee","cat":"Bidding & contracts","def":"The bid bond, cashier's check or certified check sent with a public bid to guarantee you'll sign if you win. Often 10% of the bid.","mod":14},
  {"term":"Bid shopping","abbr":"","cat":"Bidding & contracts","def":"When a contractor shows a sub's price to other subs to drive the price down after bid day. California's subcontractor listing law limits it on public work.","mod":14},
  {"term":"Bid Summary","abbr":"","also":"BID211","cat":"Bidding & contracts","def":"Caltrans's report after bid opening, listing every bidder, every unit price and each bidder's listed subs. The report code BID211 prints in the corner.","ex":"The Real Bid Lab in this course is built from the Bid Summaries of 5 Caltrans District 11 jobs.","mod":15},
  {"term":"Bid tab","abbr":"","also":"bid tabulation; bid results","cat":"Bidding & contracts","def":"The list of every bidder's price posted after a public bid opening. Study bid tabs to learn what the market charges.","mod":1},
  {"term":"Bid validity period","abbr":"","also":"validity period; quote expiration","cat":"Bidding & contracts","def":"How long your price holds. Public bids stay binding for a set number of days after opening. Your sub quote should say how long it's good for.","mod":13},
  {"term":"Bidder inquiry","abbr":"","cat":"Bidding & contracts","def":"Caltrans's name for a question asked during bidding. Answers are posted for all bidders to see.","mod":12},
  {"term":"Bioretention","abbr":"","also":"bioswale; rain garden","cat":"Hardscape & site work","def":"A planted area with special soil that soaks up and cleans storm water. Its soil, rock and plants are strictly specified.","mod":7},
  {"term":"Blue tops","abbr":"","also":"grade stakes","cat":"Grading, demo & erosion control","def":"Stakes driven so their tops (painted blue) are at finished grade. Used for fine grading.","mod":4},
  {"term":"Board foot","abbr":"BF","cat":"Units & measurement","def":"A unit of lumber: 1 foot by 1 foot by 1 inch thick. MBF means 1,000 board feet.","mod":0},
  {"term":"Bollard","abbr":"","cat":"Hardscape & site work","def":"A short post that blocks vehicles or marks a path. Some have lights.","mod":7},
  {"term":"Bond of qualifying individual","abbr":"BQI","cat":"Licensing, insurance & bonds","def":"A $25,000 bond required when a company's license is qualified by an RME, or by an RMO who owns less than 10% of the company.","mod":2},
  {"term":"Bond premium","abbr":"","also":"bond rate; bond cost","cat":"Licensing, insurance & bonds","def":"What the surety charges for a bond, usually a percent of the contract amount. Rates depend on your credit, finances and history.","mod":10},
  {"term":"Bonded fiber matrix","abbr":"BFM","cat":"Grading, demo & erosion control","def":"A sprayed erosion cover of fiber and binder that sticks to the soil and forms a mat.","ex":"Caltrans 11-422004 item 40: Bonded Fiber Matrix (SQFT), 47,600 SQFT.","mod":7},
  {"term":"Bonding agent","abbr":"","also":"surety broker","cat":"Licensing, insurance & bonds","def":"The broker who places your bonds with surety companies and helps build your bonding capacity.","mod":2},
  {"term":"Bonding capacity","abbr":"","also":"bonding line; bond limit","cat":"Licensing, insurance & bonds","def":"How much bonded work a surety will back, for one job and in total.","mod":2},
  {"term":"Booster pump","abbr":"","also":"pump station","cat":"Irrigation","def":"A pump that raises water pressure when the supply is too low for the system.","mod":6},
  {"term":"Botanical name","abbr":"","also":"scientific name; Latin name","cat":"Planting & soil","def":"A plant's scientific name, genus and species, like Aloe vera. Common names can mean several different plants, so always price from the botanical name.","mod":7},
  {"term":"Bottom of wall","abbr":"BW","also":"BOW","cat":"Plans & drawings","def":"The finished grade elevation at the base of a wall.","mod":4},
  {"term":"Boulder","abbr":"","also":"decorative boulder","cat":"Hardscape & site work","def":"A large rock set as a feature, priced each by size or by the ton, plus setting with equipment.","ex":"Caltrans 11-422004 item 19: Decorative Boulders, 20 EA.","mod":7},
  {"term":"Break-even","abbr":"","also":"breakeven point","cat":"Money & estimating","def":"The price where you cover all costs and overhead but make no profit.","mod":10},
  {"term":"Broom finish","abbr":"","cat":"Hardscape & site work","def":"A concrete finish brushed with a broom for a non-slip surface.","mod":7},
  {"term":"Brown trunk height","abbr":"BTH","cat":"Planting & soil","def":"A palm's height measured on the brown, woody trunk only, not counting the green fronds.","mod":7},
  {"term":"Bubbler","abbr":"","also":"tree bubbler; root watering","cat":"Irrigation","def":"A head that floods a small area, usually at a tree basin.","mod":6},
  {"term":"Budget","abbr":"","cat":"Money & estimating","def":"The estimate turned into the job's cost targets by cost code, used to track the job.","mod":16},
  {"term":"Build America, Buy America","abbr":"BABA","cat":"Public works & compliance","def":"A 2021 federal law that extends “buy American” rules to more construction materials on federally funded jobs.","mod":15},
  {"term":"Builder's risk","abbr":"","also":"course of construction","cat":"Licensing, insurance & bonds","def":"Property insurance on the work being built, usually bought by the owner or GC. Ask whether your stored materials are covered.","mod":16},
  {"term":"Bulb","abbr":"","cat":"Planting & soil","def":"A plant grown from a bulb or similar underground storage part. Caltrans calls this Plant Group E.","mod":7},
  {"term":"Burdened labor rate","abbr":"","also":"loaded rate","cat":"Money & estimating","def":"Wage plus labor burden: the true cost of one hour of a worker.","mod":9},
  {"term":"Bust","abbr":"","also":"busted bid; blown bid","cat":"Construction phrases & jargon","def":"Slang for a bid with a big mistake in it, like a missed item or a wrong quantity. Also used for a job that loses money.","mod":10},
  {"term":"Buy America","abbr":"","cat":"Public works & compliance","def":"Federal rules on federal-aid highway jobs requiring that steel and iron (and under newer rules, other materials) be made in the U.S. Read the job's special provisions for what applies.","ex":"Caltrans 11-428704 was a federal-aid job (ACIM-8051-(641)E on its Bid Summary).","mod":15},
  {"term":"Buyout","abbr":"","cat":"Construction phrases & jargon","def":"After a GC wins, the step where it signs subcontracts and purchase orders. Prices and scope sometimes get pushed again at buyout.","mod":16},
  {"term":"By others","abbr":"","cat":"Construction phrases & jargon","def":"Work someone else will do and that is not in your price.","ex":"Example: “Electrical service to the controller by others.”","mod":13},
  {"term":"C-8 license","abbr":"C-8","also":"Concrete Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for concrete work: forms, placing and finishing.","mod":2},
  {"term":"C-10 license","abbr":"C-10","also":"Electrical Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for electrical work. Line-voltage power to controllers and lighting is often C-10 work.","mod":2},
  {"term":"C-12 license","abbr":"C-12","also":"Earthwork and Paving Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for digging, moving and compacting earth, and paving.","mod":2},
  {"term":"C-13 license","abbr":"C-13","also":"Fencing Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for building fences and gates.","mod":2},
  {"term":"C-27 license","abbr":"C-27","also":"Landscaping Contractor","cat":"Licensing, insurance & bonds","def":"California's landscaping contractor license. It covers planting, irrigation, soil prep, walks, drainage, garden walls, fences and other landscape features (16 CCR 832.27).","mod":2},
  {"term":"C-29 license","abbr":"C-29","also":"Masonry Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for brick, block and stone work, including retaining and seat walls.","mod":2},
  {"term":"C-34 license","abbr":"C-34","also":"Pipeline Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for pipelines, including water lines and conduits.","mod":2},
  {"term":"C-36 license","abbr":"C-36","also":"Plumbing Contractor","cat":"Licensing, insurance & bonds","def":"California specialty license for plumbing. Some water service and backflow work near buildings can fall under it.","mod":2},
  {"term":"C-49 license","abbr":"C-49","also":"Tree and Palm Contractor","cat":"Licensing, insurance & bonds","def":"California license for planting, pruning, trimming and removing trees and palms. New in 2024; it replaced new applications for the C-61/D-49 tree service license.","mod":2},
  {"term":"C-61/D-12 license","abbr":"C-61/D-12","also":"Synthetic Products","cat":"Licensing, insurance & bonds","def":"A limited specialty license for installing synthetic products, such as synthetic turf.","mod":2},
  {"term":"C-61/D-49 license","abbr":"C-61/D-49","also":"Tree Service","cat":"Licensing, insurance & bonds","def":"The older limited specialty for tree service. CSLB stopped taking new applications after 2023, but existing holders may keep it. New applicants get the C-49.","mod":2},
  {"term":"C900 PVC","abbr":"C900","also":"AWWA C900","cat":"Irrigation","def":"Heavy PVC water pipe made to the AWWA C900 standard, sized like ductile iron pipe, with gasketed joints. Used for large mains.","ex":"Caltrans 11-428804 item 70: 6\" C900 (DR-14) PVC Pipe Recycled Water Distribution Line, LF.","mod":6},
  {"term":"CAC-2","abbr":"","cat":"Public works & compliance","def":"The form sent with training fund contributions to the California Apprenticeship Council.","mod":11},
  {"term":"Cal/OSHA","abbr":"","also":"DOSH","cat":"Agencies & organizations","def":"California's workplace safety agency (Division of Occupational Safety and Health). Its rules are in Title 8 of the California Code of Regulations.","mod":2},
  {"term":"Calendar day","abbr":"","cat":"Bidding & contracts","def":"Every day on the calendar, including weekends and holidays.","mod":3},
  {"term":"California Coastal Commission permit","abbr":"CDP","also":"coastal development permit","cat":"Public works & compliance","def":"A permit for development in the coastal zone. Its conditions can limit when and how you work.","ex":"City of San Diego K-24-1952 includes its Coastal Commission permit as an appendix.","mod":3},
  {"term":"California Department of Tax and Fee Administration","abbr":"CDTFA","cat":"Agencies & organizations","def":"The state agency that collects sales and use tax. Its rules say who owes tax on construction materials.","mod":8},
  {"term":"California Department of Transportation","abbr":"Caltrans","cat":"Agencies & organizations","def":"The state highway agency. It hires contractors for freeway landscape, irrigation and erosion control work through public bids.","mod":15},
  {"term":"California Environmental Quality Act","abbr":"CEQA","cat":"Public works & compliance","def":"The state law requiring agencies to study and reduce a project's environmental impacts before approving it. The results can add rules your crew must follow, like nesting bird surveys or work windows.","mod":3},
  {"term":"California Highway Patrol","abbr":"CHP","cat":"Agencies & organizations","def":"State police. On Caltrans jobs, CHP officers can provide traffic breaks through COZEEP.","mod":15},
  {"term":"California Landscape Contractors Association","abbr":"CLCA","cat":"Agencies & organizations","def":"A trade group for California landscape contractors, with local chapters, training and certifications.","mod":3},
  {"term":"California native plant","abbr":"","also":"native","cat":"Planting & soil","def":"A plant that grows naturally in California. Often required on public and habitat jobs.","mod":7},
  {"term":"California Stormwater Quality Association","abbr":"CASQA","cat":"Agencies & organizations","def":"The group that runs the training and certification for QSDs and QSPs and publishes BMP handbooks.","mod":7},
  {"term":"California Unified Certification Program","abbr":"CUCP","cat":"Agencies & organizations","def":"The program that certifies DBEs in California. One certification is accepted by all participating agencies.","mod":14},
  {"term":"Caliper","abbr":"CAL","cat":"Planting & soil","def":"The trunk thickness of a tree, measured a set height above the ground. Nursery standards set where to measure.","mod":7},
  {"term":"Caliper inch","abbr":"","also":"caliper","cat":"Planting & soil","def":"Tree trunk thickness in inches. Some specs and tree replacement rules count trees by caliper inches.","mod":7},
  {"term":"Callback","abbr":"","also":"warranty call","cat":"Construction phrases & jargon","def":"Going back to fix something after you thought you were done, often under warranty.","mod":16},
  {"term":"Callout","abbr":"","also":"label; leader","cat":"Plans & drawings","def":"Text on a plan, with a line pointing to what it describes, giving a size, type or quantity.","ex":"Caltrans planting plans show callouts like a count, plant code and size.","mod":4},
  {"term":"Capabilities statement","abbr":"","also":"company profile","cat":"Bidding & contracts","def":"A one-page summary of your company: licenses, work types, past jobs, bonding and contacts. Send it to GCs and agencies.","mod":2},
  {"term":"Carry","abbr":"","also":"carry a number","cat":"Construction phrases & jargon","def":"To include an amount in your bid.","ex":"Example: “We carried $5,000 for the controller because the supplier quote didn't come in.”","mod":13},
  {"term":"Cash flow","abbr":"","cat":"Money & estimating","def":"When money actually goes out and comes in. You pay crews weekly and suppliers in 30 days, but may get paid 45 to 60 days after billing, less retention.","mod":3},
  {"term":"Catch basin","abbr":"CB","also":"inlet; drain inlet","cat":"Hardscape & site work","def":"A box with a grate or opening that collects storm water into a pipe.","mod":4},
  {"term":"Centerline","abbr":"CL","also":"℄; C/L","cat":"Plans & drawings","def":"The middle line of a road, wall or pipe. Stations and offsets are measured from it.","mod":4},
  {"term":"Central control","abbr":"","also":"central system","cat":"Irrigation","def":"Software that runs many controllers from one computer, by radio, cell or internet.","mod":6},
  {"term":"Certificate of compliance","abbr":"COC","cat":"Specifications","def":"A signed statement from a supplier that its material meets the specs. Some agencies accept materials this way instead of testing.","ex":"City of San Diego K-24-1952 lists materials typically accepted by certificate of compliance.","mod":5},
  {"term":"Certified payroll","abbr":"CPR","also":"certified payroll record","cat":"Public works & compliance","def":"A weekly payroll report for public work, listing each worker, craft, hours and pay, signed under penalty of perjury. You must give a certified copy within 10 days of a written request.","mod":11},
  {"term":"Chain link fence","abbr":"CLF","cat":"Hardscape & site work","def":"Woven steel wire fence on posts.","ex":"Caltrans 11-428804 item 87: Chain Link Fence (Type CL-6), 10 LF.","mod":7},
  {"term":"Change directive","abbr":"CCD","also":"construction change directive","cat":"Bidding & contracts","def":"An owner's written order to do changed work before the price is agreed. Track your actual costs closely so you can get paid.","mod":16},
  {"term":"Change order","abbr":"CO","cat":"Bidding & contracts","def":"A signed, written change to the contract's scope, price or time. Don't do extra work without one, or at least a written direction.","mod":16},
  {"term":"Change order request","abbr":"COR","also":"proposed change order; PCO; change request","cat":"Bidding & contracts","def":"Your written request for a change order, with your price and backup.","mod":16},
  {"term":"Changeable message sign","abbr":"CMS","also":"PCMS; message board","cat":"Construction phrases & jargon","def":"A trailer-mounted electronic sign that warns drivers of work ahead.","ex":"Caltrans 11-428704 item 6: Portable Changeable Message Sign (EA), 2 EA.","mod":15},
  {"term":"Check and test existing irrigation","abbr":"","cat":"Irrigation","def":"Caltrans work to run and inspect an existing system before you change it, so problems found are on record.","ex":"Caltrans 11-428704 item 32: Check and Test Existing Irrigation Facilities, LS.","mod":15},
  {"term":"Check dam","abbr":"","cat":"Grading, demo & erosion control","def":"A small barrier, often gravel bags or fiber rolls, across a ditch to slow water and catch sediment.","ex":"Caltrans 11-431064 item 15: Temporary Check Dam, 1,990 LF.","mod":7},
  {"term":"City of San Diego Engineering & Capital Projects","abbr":"E&CP","cat":"Agencies & organizations","def":"The City department that designs and builds City projects like parks, streets and pipelines, and runs their construction contracts.","mod":3},
  {"term":"Civil sheets","abbr":"C","cat":"Plans & drawings","def":"Grading, drainage, paving and utility sheets by the civil engineer. They show grades and drains your landscape must match.","mod":4},
  {"term":"Claim","abbr":"","cat":"Bidding & contracts","def":"A formal demand for more money or time that the owner has refused. Contracts set strict written notice deadlines, so read them early.","mod":16},
  {"term":"Clarification","abbr":"","cat":"Bidding & contracts","def":"A note in your proposal explaining how you read an unclear item, or a condition your price depends on.","mod":13},
  {"term":"Class 200 PVC","abbr":"CL 200","also":"SDR 21","cat":"Irrigation","def":"PVC pipe rated for 200 PSI at every size, with thinner walls than Schedule 40. Often used for laterals.","mod":6},
  {"term":"Class 315 PVC","abbr":"CL 315","also":"SDR 13.5","cat":"Irrigation","def":"PVC pipe rated for 315 PSI at every size. Often used for mainline.","ex":"Caltrans 11-428704 item 63: 4\" Plastic Pipe (Class 315) (Supply Line), 7,493 LF.","mod":6},
  {"term":"Class C license","abbr":"","also":"specialty license","cat":"Licensing, insurance & bonds","def":"Any of California's specialty trade licenses, like C-27 landscaping or C-10 electrical.","mod":2},
  {"term":"Class code","abbr":"","also":"workers' comp class code","cat":"Licensing, insurance & bonds","def":"The category that sets your workers' comp rate. Landscape work is usually class 0042 in California.","mod":9},
  {"term":"Clean bid","abbr":"","cat":"Construction phrases & jargon","def":"A proposal with no confusing exclusions or conditions, easy for a GC to compare.","mod":13},
  {"term":"Clear trunk height","abbr":"CTH","cat":"Planting & soil","def":"Palm height from the ground to where the fronds start.","mod":7},
  {"term":"Clearing and grubbing","abbr":"C&G","cat":"Grading, demo & erosion control","def":"Removing plants, roots, stumps and debris from a work area before grading.","ex":"Caltrans 11-430674 item 25: Clearing and Grubbing (LS), LS.","mod":7},
  {"term":"Closeout","abbr":"","also":"project closeout","cat":"Bidding & contracts","def":"The end of the job: punch list, as-builts, O&M manuals, warranties, lien releases and final payment.","mod":16},
  {"term":"Cobble","abbr":"","also":"river rock","cat":"Hardscape & site work","def":"Rounded stones, usually 3 to 8 inches, used in swales and as mulch.","mod":7},
  {"term":"Combination air release valve","abbr":"CARV","also":"combination air valve","cat":"Irrigation","def":"A valve that lets out large amounts of air when a pipe fills, and small air pockets while running.","ex":"Caltrans 11-428704 item 65: 1\" Combination Air Release Valve, 8 EA.","mod":6},
  {"term":"Commercial auto liability","abbr":"","also":"auto","cat":"Licensing, insurance & bonds","def":"Insurance for your trucks and other vehicles. Contracts set the minimum limit.","mod":2},
  {"term":"Commercial general liability","abbr":"CGL","also":"general liability; GL","cat":"Licensing, insurance & bonds","def":"Insurance for injury to others or damage to their property caused by your work. Contracts set the limits, often per occurrence and aggregate.","mod":2},
  {"term":"Commercially useful function","abbr":"CUF","cat":"Public works & compliance","def":"A rule that a DBE or other certified firm counted toward a goal must actually do, manage and supervise its work, not just pass money through.","mod":14},
  {"term":"Common wire","abbr":"","also":"ground wire; return wire","cat":"Irrigation","def":"The shared return wire for all valves on a conventional wired system, usually white.","mod":6},
  {"term":"Community benefits agreement","abbr":"CBA","also":"community workforce agreement; CWA","cat":"Public works & compliance","def":"An agreement on some public projects setting local hiring, training or other community goals that contractors must meet.","mod":3},
  {"term":"Compacted cubic yard","abbr":"CCY","cat":"Units & measurement","def":"Soil measured after it is placed and compacted.","mod":0},
  {"term":"Compaction","abbr":"","cat":"Grading, demo & erosion control","def":"Packing soil tight with a roller, plate or wacker so it won't settle.","mod":7},
  {"term":"Company overhead","abbr":"","also":"general overhead; G&A; home office overhead","cat":"Money & estimating","def":"The cost of running the business, shared by all jobs: office, estimator, accounting, yard, insurance not charged to jobs.","mod":10},
  {"term":"Competent person","abbr":"","cat":"Public works & compliance","def":"A worker trained to spot hazards and with authority to fix them. Required on site for trenching and excavation work.","mod":9},
  {"term":"Compost","abbr":"","also":"organic amendment","cat":"Planting & soil","def":"Decayed organic matter used to improve soil. Specs set its quality and rate.","ex":"Caltrans 11-428704 item 68: Compost (CY), 290 CY.","mod":7},
  {"term":"Concrete masonry unit","abbr":"CMU","also":"block","cat":"Hardscape & site work","def":"Concrete block used for walls.","mod":7},
  {"term":"Concrete washout","abbr":"","also":"washout","cat":"Grading, demo & erosion control","def":"A lined pit or container where concrete trucks and tools are rinsed, so the wash water stays out of storm drains.","ex":"Caltrans 11-422004 item 13: Temporary Concrete Washout, LS.","mod":7},
  {"term":"Conditional bid","abbr":"","also":"qualified bid","cat":"Bidding & contracts","def":"A public bid with added conditions or exceptions. It can be rejected as nonresponsive.","mod":13},
  {"term":"Conditional waiver and release","abbr":"","also":"conditional release","cat":"Bidding & contracts","def":"A lien release that takes effect only when you're actually paid. California requires statutory forms.","mod":16},
  {"term":"Conduit","abbr":"","cat":"Irrigation","def":"A pipe that holds and protects wire. Electrical conduit for controllers is often a different trade.","mod":6},
  {"term":"Consent of surety","abbr":"","cat":"Licensing, insurance & bonds","def":"The surety's written OK, often needed before final payment or release of retention.","mod":16},
  {"term":"Construction area signs","abbr":"","cat":"Construction phrases & jargon","def":"Warning signs along a highway telling drivers about the work.","ex":"Caltrans 11-428704 item 3: Construction Area Signs, LS.","mod":15},
  {"term":"Construction documents","abbr":"CDs","cat":"Plans & drawings","def":"The finished plans and specs used to bid and build. Earlier design stages are often called schematic design (SD) and design development (DD).","mod":4},
  {"term":"Construction General Permit","abbr":"CGP","cat":"Public works & compliance","def":"California's statewide storm water permit for construction that disturbs 1 acre or more of soil, or less if part of a larger plan. It requires a SWPPP. The current permit took effect September 1, 2023.","mod":7},
  {"term":"Construction manager","abbr":"CM","cat":"Bidding & contracts","def":"A firm hired to manage the project for the owner. Under CM at-risk, it also guarantees the price and hires the subs.","mod":1},
  {"term":"Construction manager at-risk","abbr":"CMAR","also":"CM at-risk; CM/GC","cat":"Bidding & contracts","def":"A delivery method where a construction firm joins during design, then guarantees a maximum price and hires subs, often through bids.","mod":1},
  {"term":"Construction schedule","abbr":"","also":"baseline schedule; CPM schedule","cat":"Construction phrases & jargon","def":"The timeline for the whole job. Your landscape work has to fit the dates in it.","mod":16},
  {"term":"Construction Specifications Institute","abbr":"CSI","cat":"Agencies & organizations","def":"The group that created MasterFormat, the numbering system for project manual specs.","mod":5},
  {"term":"Construction staking","abbr":"","also":"survey staking; layout","cat":"Plans & drawings","def":"Stakes set by a surveyor marking lines and grades. Specs say whether the owner or you pay for it.","mod":4},
  {"term":"Consumer (sales tax)","abbr":"","cat":"Money & estimating","def":"For sales tax, the one who uses the material and owes the tax. Usually the contractor for materials it installs on real property.","mod":8},
  {"term":"Container size","abbr":"","also":"can size","cat":"Planting & soil","def":"The nursery size a plant comes in, like #1, #5, #15 or 24\" box. Each size is priced as its own line.","mod":7},
  {"term":"Contingency","abbr":"","cat":"Money & estimating","def":"Money in a bid for a named risk that can't be priced exactly. Owners also keep contingency for changes.","mod":10},
  {"term":"Contour","abbr":"","also":"contour line","cat":"Plans & drawings","def":"A line on a grading plan connecting points of equal elevation. Close lines mean steep ground.","mod":4},
  {"term":"Contract documents","abbr":"","cat":"Bidding & contracts","def":"The signed agreement plus the plans, specs, general and special conditions, addenda and change orders that together make the contract.","mod":5},
  {"term":"Contract growing","abbr":"","also":"grow-out","cat":"Planting & soil","def":"Paying a nursery to grow plants for your job ahead of time, when big quantities or special plants won't be on hand otherwise.","mod":8},
  {"term":"Contract item code","abbr":"","also":"item code","cat":"Bidding & contracts","def":"The 6-digit Caltrans code for each standard bid item. The same code means the same work on every job, so you can compare prices across jobs.","ex":"Caltrans item code 204099 is Plant Establishment Work on all five Real Bid Lab jobs.","mod":15},
  {"term":"Contract time","abbr":"","cat":"Bidding & contracts","def":"The time allowed to finish, in working days or calendar days.","ex":"Caltrans 11-428704: 120 working days for the work, and 370 working days including 250 days of plant establishment.","mod":3},
  {"term":"Contractor price","abbr":"","also":"price tier; contractor discount","cat":"Money & estimating","def":"Your account's discount level at a supplier, often based on how much you buy.","mod":8},
  {"term":"Contractor-controlled insurance program","abbr":"CCIP","also":"wrap-up","cat":"Licensing, insurance & bonds","def":"Like an OCIP, but bought by the GC to cover all subs on the job.","mod":2},
  {"term":"Contractor's Corner","abbr":"","also":"Contractors Corner","cat":"Agencies & organizations","def":"Caltrans's web portal where advertised projects, plans, specs and addenda are posted.","mod":15},
  {"term":"Contractor's pollution liability","abbr":"CPL","also":"pollution","cat":"Licensing, insurance & bonds","def":"Insurance for pollution claims from your work, like a fuel spill or herbicide drift. Some public contracts require it.","mod":2},
  {"term":"Contractors State License Board","abbr":"CSLB","cat":"Agencies & organizations","def":"The California agency that licenses and disciplines contractors. Check any company's license at cslb.ca.gov.","mod":2},
  {"term":"Control and neutral conductors","abbr":"CNC","cat":"Irrigation","def":"Caltrans name for the controller wiring to the valves: control wires and the common (neutral).","ex":"Caltrans 11-428704 item 36: Control and Neutral Conductors, LS.","mod":15},
  {"term":"Control joint","abbr":"CJ","also":"score joint","cat":"Hardscape & site work","def":"A groove in concrete that controls where it cracks.","mod":7},
  {"term":"Control wire","abbr":"","also":"zone wire; station wire","cat":"Irrigation","def":"The wire from the controller to each valve. Each valve needs its own control wire on a conventional system.","mod":6},
  {"term":"Controller","abbr":"","also":"timer; clock","cat":"Irrigation","def":"The device that turns irrigation zones on and off on a schedule.","ex":"Caltrans 11-428704 item 41: 40 Station Irrigation Controller and Enclosure '97B', 1 EA.","mod":6},
  {"term":"Controller chart","abbr":"","cat":"Irrigation","def":"A reduced, laminated copy of the irrigation plan, color coded by zone, kept in the controller. A common closeout requirement.","mod":16},
  {"term":"Controller enclosure","abbr":"","also":"cabinet; pedestal","cat":"Irrigation","def":"A locking metal cabinet that holds a commercial controller outdoors.","ex":"Caltrans 11-422004 item 31: Irrigation Controller Enclosure Cabinet, 1 EA.","mod":6},
  {"term":"Cost code","abbr":"","cat":"Money & estimating","def":"A label for each type of task so hours and costs can be tracked by task.","mod":9},
  {"term":"Cost per square foot","abbr":"","also":"$/SF","cat":"Money & estimating","def":"Total price divided by the landscape area. Useful to check a bid against similar jobs, never as a way to price one.","mod":10},
  {"term":"Cost to complete","abbr":"","cat":"Money & estimating","def":"How much more money you expect to spend to finish a job.","mod":16},
  {"term":"Cost-plus","abbr":"","also":"cost plus fee; cost-reimbursable","cat":"Bidding & contracts","def":"A contract that pays your actual costs plus a fee. Common on negotiated private work.","mod":1},
  {"term":"County of San Diego","abbr":"","cat":"Agencies & organizations","def":"The county government. It bids parks, roads and facility work, separate from the City of San Diego.","mod":3},
  {"term":"Courtesy bid","abbr":"","cat":"Construction phrases & jargon","def":"A bid sent mainly to stay on good terms with a GC, without a serious try to win. Use rarely. A polite “no-bid” is often better.","mod":3},
  {"term":"Cover sheet","abbr":"","also":"title sheet","cat":"Plans & drawings","def":"The first sheet of a plan set, with project name, location map, sheet index and often general notes.","mod":4},
  {"term":"Coverage","abbr":"","also":"head-to-head coverage","cat":"Irrigation","def":"How well sprinklers cover an area. Head-to-head means each head throws water all the way to the next head.","mod":6},
  {"term":"COZEEP","abbr":"COZEEP","also":"Construction Zone Enhanced Enforcement Program","cat":"Agencies & organizations","def":"A program where CHP officers support traffic control on Caltrans work zones. Caltrans deducts its cost from your payment if you use it for traffic breaks.","ex":"Caltrans 11-428704 special provisions set CHP COZEEP support at $115 per officer hour.","mod":15},
  {"term":"Craft","abbr":"","also":"classification","cat":"Public works & compliance","def":"The trade category a worker is paid under on public work, like Landscape/Irrigation Laborer or Operating Engineer. Pay by the work actually done, not job title.","mod":11},
  {"term":"Crash cushion","abbr":"","also":"impact attenuator","cat":"Construction phrases & jargon","def":"A device at the end of a barrier that absorbs the hit if a car strikes it.","ex":"Caltrans 11-428704 item 8: Alternative Temporary Crash Cushion System, 6 EA.","mod":15},
  {"term":"Credit application","abbr":"","also":"credit app","cat":"Money & estimating","def":"The form a supplier uses to approve your account and credit limit.","mod":8},
  {"term":"Crew day","abbr":"","also":"crew-day","cat":"Money & estimating","def":"One full crew working one full day. A handy unit for pricing and scheduling.","mod":9},
  {"term":"Crew rate","abbr":"","cat":"Money & estimating","def":"The combined hourly cost of everyone on a crew, including burden.","mod":9},
  {"term":"Critical path","abbr":"CPM","also":"critical path method","cat":"Construction phrases & jargon","def":"The chain of tasks that sets the finish date. If a task on the critical path slips, the whole job slips. Landscape is often near the end of it.","mod":16},
  {"term":"Cross-connection","abbr":"","cat":"Public works & compliance","def":"Any link where dirty or non-drinking water could flow back into the drinking water supply. Backflow preventers and recycled water rules exist to stop this.","mod":6},
  {"term":"Cross-connection test station","abbr":"CCTS","cat":"Irrigation","def":"A test point used to prove recycled and drinking water systems are fully separate.","ex":"Shown on Caltrans 11-428704 plans with the recycled water connection assemblies.","mod":15},
  {"term":"Crushed miscellaneous base","abbr":"CMB","cat":"Hardscape & site work","def":"A recycled crushed base rock allowed by the Greenbook and many local agencies.","mod":7},
  {"term":"Cubic foot","abbr":"CF","also":"CU FT; ft³","cat":"Units & measurement","def":"A volume 1 foot long, 1 foot wide and 1 foot deep. 27 cubic feet make 1 cubic yard.","mod":0},
  {"term":"Cubic yard","abbr":"CY","also":"CU YD; yd³; yard","cat":"Units & measurement","def":"A volume 3 feet by 3 feet by 3 feet (27 cubic feet). Soil, mulch, compost and concrete are sold by the yard.","ex":"Caltrans 11-428704 item 31: Wood Mulch, 190 CY.","mod":0},
  {"term":"Cultivar","abbr":"cv.","also":"variety","cat":"Planting & soil","def":"A named variety of a plant, written in single quotes, like 'Little Ollie.' Some cultivars are hard to find.","mod":7},
  {"term":"Curb and gutter","abbr":"C&G","cat":"Hardscape & site work","def":"The concrete curb and drain channel at a street edge. Usually civil scope, but it sets your planting edge and grades.","mod":4},
  {"term":"Curb ramp","abbr":"","also":"ADA ramp","cat":"Hardscape & site work","def":"A short ramp from a sidewalk down to the street, built to accessibility rules.","mod":7},
  {"term":"Cut","abbr":"","also":"excavation","cat":"Grading, demo & erosion control","def":"Digging soil out to lower the grade.","mod":7},
  {"term":"Cutting","abbr":"","also":"rooted cutting","cat":"Planting & soil","def":"A piece of a plant, like iceplant, planted to grow roots. Caltrans calls this Plant Group H.","ex":"Caltrans 11-428704 item 25: Plant (Group H), 61,975 EA iceplant cuttings, an (F) item.","mod":7},
  {"term":"Daily report","abbr":"","also":"daily log; dailies","cat":"Construction phrases & jargon","def":"A short written record of each day: crew, hours, equipment, work done, weather, visitors and problems. Your best evidence in a dispute.","mod":16},
  {"term":"DAS 140","abbr":"","cat":"Public works & compliance","def":"The form that notifies apprenticeship committees that you have a public works contract. Due within 10 days of signing the contract, and no later than the first day you have workers on the job.","mod":11},
  {"term":"DAS 142","abbr":"","cat":"Public works & compliance","def":"The form requesting apprentices from an apprenticeship committee. Send it at least 3 business days before you need them.","mod":11},
  {"term":"Davis-Bacon Act","abbr":"DBA","also":"Davis-Bacon","cat":"Public works & compliance","def":"The federal prevailing wage law for federal and many federally funded construction jobs. On those jobs you pay the higher of the federal or state rate.","mod":11},
  {"term":"Day","abbr":"DAY","cat":"Units & measurement","def":"A pay unit for items paid by the day.","ex":"Caltrans 11-422004 item 5: Stationary Impact Attenuator Vehicle, 20 DAY.","mod":0},
  {"term":"Debarment","abbr":"","cat":"Public works & compliance","def":"Being banned from public contracts for a period, for things like serious wage violations or false statements.","mod":14},
  {"term":"Debris","abbr":"","cat":"Grading, demo & erosion control","def":"Trash, broken concrete, plants and other waste from the work. Price hauling and dump fees.","mod":7},
  {"term":"Decoder","abbr":"","cat":"Irrigation","def":"A small module at each valve on a two-wire system that tells the valve when to open.","mod":6},
  {"term":"Decomposed granite","abbr":"DG","cat":"Hardscape & site work","def":"Crushed granite used for paths and areas, compacted in place. Priced by SF at a set depth.","ex":"Caltrans 11-430674 item 45: Decomposed Granite, 55,900 SQFT.","mod":7},
  {"term":"Deductible","abbr":"","also":"self-insured retention; SIR","cat":"Licensing, insurance & bonds","def":"The part of each claim you pay yourself before insurance pays.","mod":2},
  {"term":"Deductive alternate","abbr":"","also":"deduct alternate; deduct alt","cat":"Bidding & contracts","def":"Work the owner may take out of the job, priced as a credit.","mod":14},
  {"term":"Delay","abbr":"","cat":"Bidding & contracts","def":"Lost time on a job. An excusable delay, one you didn't cause, can earn extra time; some also earn extra money.","mod":16},
  {"term":"Delivery method","abbr":"","also":"project delivery","cat":"Bidding & contracts","def":"How the owner buys the project: design-bid-build, design-build, CM at-risk, negotiated and so on.","mod":1},
  {"term":"Demobilization","abbr":"demob","cat":"Money & estimating","def":"Removing crews, equipment and temporary facilities when work is done.","mod":9},
  {"term":"Demolition","abbr":"demo","cat":"Grading, demo & erosion control","def":"Tearing out existing work like paving, walls or old landscape. Price the haul-off and dump fees too.","mod":7},
  {"term":"Department of General Services","abbr":"DGS","cat":"Agencies & organizations","def":"The California agency that certifies Small Businesses (SB) and DVBEs for state contracting.","mod":14},
  {"term":"Department of Industrial Relations","abbr":"DIR","cat":"Agencies & organizations","def":"The California department that sets prevailing wage rates, registers public works contractors and enforces public works labor law.","mod":2},
  {"term":"Department of Water Resources","abbr":"DWR","cat":"Agencies & organizations","def":"The state water agency that publishes the Model Water Efficient Landscape Ordinance.","mod":5},
  {"term":"Design-assist","abbr":"","cat":"Bidding & contracts","def":"A sub joins early to give pricing and building advice while the designer finishes the plans.","mod":1},
  {"term":"Design-bid-build","abbr":"DBB","also":"plan and spec","cat":"Bidding & contracts","def":"The owner hires a designer first, then takes bids on the finished plans. The most common method for public work.","ex":"City of San Diego bid numbers show it, like K-24-1952-DBB-3-A.","mod":1},
  {"term":"Design-build","abbr":"DB","also":"D/B","cat":"Bidding & contracts","def":"One company or team designs and builds the project under one contract.","mod":1},
  {"term":"Detail","abbr":"DET","cat":"Plans & drawings","def":"A close-up drawing showing exactly how one item is built, like a valve or tree planting detail.","mod":4},
  {"term":"Detail callout","abbr":"","also":"detail bubble","cat":"Plans & drawings","def":"A circle with two numbers: the detail number on top and the sheet where it is drawn below, like 3 over L-5.1.","mod":4},
  {"term":"Detectable warning surface","abbr":"","also":"truncated domes","cat":"Hardscape & site work","def":"The bumpy tactile panel at curb ramps that warns blind pedestrians of the street.","mod":7},
  {"term":"Diameter","abbr":"DIA","also":"Ø; dia","cat":"Units & measurement","def":"The width of a circle through its center. Used for pipe, plant holes and basins.","mod":0},
  {"term":"Differing site conditions","abbr":"DSC","also":"changed conditions; unforeseen conditions","cat":"Bidding & contracts","def":"Hidden site conditions that differ from what the documents showed, like buried concrete or rock. Most public contracts allow extra pay if you give written notice right away, before disturbing the area.","mod":16},
  {"term":"DigAlert","abbr":"","also":"811; Underground Service Alert; USA","cat":"Agencies & organizations","def":"The call center for Southern California that has utility lines marked before you dig. Call 811 or file online at least 2 working days before digging.","mod":12},
  {"term":"Dimension","abbr":"DIM","cat":"Plans & drawings","def":"A measured distance written on the plan. Use written dimensions over scaled ones when they disagree.","mod":4},
  {"term":"Dimension ratio","abbr":"DR","also":"SDR","cat":"Irrigation","def":"Pipe outside diameter divided by wall thickness. Lower DR means a thicker, stronger pipe.","ex":"Caltrans 11-428804 item 70: C900 (DR-14) PVC pipe.","mod":6},
  {"term":"DIR registration","abbr":"","also":"public works contractor registration; PWCR","cat":"Public works & compliance","def":"Yearly registration with DIR required before you bid or work on most California public works, as a prime or a sub. Very small projects are exempt.","mod":2},
  {"term":"Direct burial wire","abbr":"UF","cat":"Irrigation","def":"Wire made to be buried without conduit. Irrigation control wire is usually single-strand direct burial wire.","mod":6},
  {"term":"Direct cost","abbr":"","cat":"Money & estimating","def":"Material, labor, equipment and subs that go into the installed work.","mod":10},
  {"term":"Disabled Veteran Business Enterprise","abbr":"DVBE","cat":"Public works & compliance","def":"A business at least 51% owned and run by disabled veterans, certified by the California Department of General Services. Caltrans state-funded jobs may set a DVBE goal.","mod":14},
  {"term":"Disadvantaged Business Enterprise","abbr":"DBE","cat":"Public works & compliance","def":"A small business owned by socially and economically disadvantaged people, certified under federal rules. Federal-aid jobs often set a DBE goal. In California, certification is through the CUCP.","ex":"Caltrans 11-428704 had a DBE goal of 14.0%.","mod":14},
  {"term":"Dispute Resolution Advisor","abbr":"DRA","cat":"Bidding & contracts","def":"One neutral person set up on some Caltrans jobs to help settle disputes. Meetings are paid through bid items.","ex":"Caltrans 11-428804 item 3: Dispute Resolution Advisor On-Site Meeting, 6 EA.","mod":15},
  {"term":"Dispute Resolution Board","abbr":"DRB","cat":"Bidding & contracts","def":"A panel of neutral experts set up on larger Caltrans jobs to hear disputes and make recommendations.","ex":"Caltrans 11-430674 item 3: Dispute Resolution Board On-Site Meeting, 5 EA.","mod":15},
  {"term":"Distribution uniformity","abbr":"DU","cat":"Irrigation","def":"How evenly a sprinkler zone waters an area, as a percent. Higher is better. Measured in an irrigation audit.","mod":6},
  {"term":"District 11","abbr":"D11","cat":"Agencies & organizations","def":"The Caltrans district for San Diego and Imperial counties.","mod":15},
  {"term":"District tax","abbr":"","also":"local sales tax","cat":"Money & estimating","def":"Local sales tax added on top of the 7.25% statewide base. Rates differ by city.","mod":8},
  {"term":"Division 00","abbr":"","also":"procurement and contracting requirements","cat":"Specifications","def":"MasterFormat division for bid forms, the agreement and contract conditions.","mod":5},
  {"term":"Division 01","abbr":"","also":"General Requirements","cat":"Specifications","def":"MasterFormat division for job-wide rules: submittals, schedule, temporary facilities, closeout. Applies to every trade.","mod":5},
  {"term":"Division 31","abbr":"","also":"Earthwork","cat":"Specifications","def":"MasterFormat division for site clearing, grading, excavation, fill and erosion control.","mod":5},
  {"term":"Division 32","abbr":"","also":"Exterior Improvements","cat":"Specifications","def":"MasterFormat division for paving, site improvements, irrigation and planting. Most landscape specs live here.","mod":5},
  {"term":"Division 33","abbr":"","also":"Utilities","cat":"Specifications","def":"MasterFormat division for water, sewer and storm drain utilities. Water service to your POC may be specified here.","mod":5},
  {"term":"Division of Apprenticeship Standards","abbr":"DAS","cat":"Agencies & organizations","def":"The DIR division that approves apprenticeship programs and handles DAS 140 and 142 forms.","mod":11},
  {"term":"Double check valve assembly","abbr":"DC","also":"DCVA; double check","cat":"Irrigation","def":"A backflow assembly with two check valves. Water agencies say when it's allowed instead of an RP.","mod":6},
  {"term":"Double counting","abbr":"","cat":"Money & estimating","def":"Pricing the same cost or risk in two places, which makes your bid too high.","mod":10},
  {"term":"Drip emitter","abbr":"","also":"emitter","cat":"Irrigation","def":"A small device that drips water to one plant at a set GPH.","mod":6},
  {"term":"Drip irrigation","abbr":"","also":"low-volume irrigation; micro-irrigation","cat":"Irrigation","def":"Watering plants slowly at the root zone through tubing and emitters.","mod":6},
  {"term":"Drip valve assembly","abbr":"","also":"drip control zone kit","cat":"Irrigation","def":"A valve with a filter and pressure regulator, used to run a drip zone.","mod":6},
  {"term":"Ductile iron pipe","abbr":"DIP","also":"DI pipe","cat":"Irrigation","def":"Strong iron pipe used for large mains and under heavy loads.","ex":"Caltrans 11-431064 item 45: 3\" Ductile Iron Pipe (Supply Line), 520 LF.","mod":6},
  {"term":"Dump fee","abbr":"","also":"tipping fee; disposal fee","cat":"Grading, demo & erosion control","def":"What a landfill or recycler charges to take your waste, usually per ton or per load. Green waste and clean dirt often cost less than mixed debris.","mod":9},
  {"term":"Dust control","abbr":"","cat":"Grading, demo & erosion control","def":"Watering or other steps to keep dust down, required by permits and specs.","mod":7},
  {"term":"Each","abbr":"EA","cat":"Units & measurement","def":"A pay unit for counted items: one valve, one tree, one controller.","ex":"Caltrans 11-428704 item 51: Tree Well Sprinkler Assembly, 180 EA.","mod":0},
  {"term":"Easement","abbr":"ESMT","cat":"Plans & drawings","def":"A right to use part of someone else's land for a purpose, like a utility line. Often limits planting trees over it.","mod":4},
  {"term":"Edge of pavement","abbr":"EP","also":"EOP","cat":"Plans & drawings","def":"Where the paving ends. Planting and irrigation are often laid out from it.","mod":4},
  {"term":"Edge of traveled way","abbr":"ETW","cat":"Plans & drawings","def":"The edge of the lanes used by traffic on a highway. Caltrans uses it to set how close you can work without closures.","mod":4},
  {"term":"Edging","abbr":"","also":"header; bender board","cat":"Hardscape & site work","def":"A strip of steel, plastic, wood or concrete that separates planting, turf and paths.","ex":"Caltrans 11-430674 item 47: Edging, 3,660 LF.","mod":7},
  {"term":"Electric service for irrigation","abbr":"","also":"power service","cat":"Irrigation","def":"The power supply and meter pedestal that feed a controller. On Caltrans jobs it is often a separate item, done by an electrical sub.","ex":"Caltrans 11-428704 item 69: Electric Service for Irrigation, LS (listed to an electrical sub by both of the two low bidders).","mod":15},
  {"term":"Electrical sheets","abbr":"E","cat":"Plans & drawings","def":"Sheets showing power to controllers, lighting and pumps. Often a different trade's scope, so check who carries what.","ex":"Caltrans 11-428704: E-1 and E-2, electric service for irrigation.","mod":4},
  {"term":"Electronic certified payroll","abbr":"eCPR","cat":"Public works & compliance","def":"Certified payroll uploaded online to DIR. Contractors must submit at least monthly while working on a covered public job.","mod":11},
  {"term":"Elevation (height)","abbr":"EL","also":"ELEV","cat":"Plans & drawings","def":"The height of a point above a reference level, in feet.","ex":"Example: “FG 102.50” means finished grade at elevation 102.50 feet.","mod":4},
  {"term":"Elevation (view)","abbr":"","cat":"Plans & drawings","def":"A drawing showing the side of something, like a wall face, instead of the top view.","mod":4},
  {"term":"Emerging Local Business Enterprise","abbr":"ELBE","cat":"Public works & compliance","def":"A City of San Diego certification for smaller local businesses below a lower size limit than SLBE. City jobs often set SLBE/ELBE goals.","mod":2},
  {"term":"Employer payments","abbr":"","also":"fringe benefits; fringe","cat":"Public works & compliance","def":"Health, pension, vacation, training and other amounts paid on top of the basic hourly rate in prevailing wage.","mod":11},
  {"term":"Employer's liability","abbr":"EL","cat":"Licensing, insurance & bonds","def":"Coverage that usually comes with workers' comp, for lawsuits by employees or their families over a work injury.","mod":2},
  {"term":"Engineer","abbr":"","also":"the Engineer","cat":"Specifications","def":"In Caltrans specs, the agency's person in charge of the contract, often the resident engineer.","mod":15},
  {"term":"Engineer of record","abbr":"EOR","also":"engineer of work","cat":"Bidding & contracts","def":"The licensed engineer whose stamp is on the plans and who answers questions about the design.","mod":1},
  {"term":"Engineer's estimate","abbr":"EE","cat":"Bidding & contracts","def":"The agency's own estimate of the project cost, often published with the bid. Bids often come in well above or below it.","ex":"Caltrans 11-428704: engineer's estimate $1,516,176.50; the winning bid was 22.43% under it.","mod":3},
  {"term":"Environmental impact report","abbr":"EIR","cat":"Public works & compliance","def":"A detailed CEQA study of a project's effects on the environment. It may set rules for construction.","mod":3},
  {"term":"Environmentally sensitive area","abbr":"ESA","cat":"Public works & compliance","def":"An area marked on the plans that you must not enter or disturb, often fenced.","ex":"ESA areas are marked on the Caltrans 11-422004 plans near Carmel Valley Road.","mod":4},
  {"term":"Equal","abbr":"EQ","cat":"Plans & drawings","def":"Means equal spacing, like “EQ, EQ, EQ” across a row of trees.","mod":4},
  {"term":"Equal Opportunity Contracting Program","abbr":"EOCP","cat":"Agencies & organizations","def":"The City of San Diego office that runs the SLBE/ELBE program and subcontracting rules on City contracts.","ex":"City of San Diego K-24-1952 lists EOCP forms you must submit.","mod":14},
  {"term":"Equipment rate","abbr":"","cat":"Money & estimating","def":"Your hourly or daily cost to own or rent and run a machine.","mod":9},
  {"term":"Erosion control","abbr":"EC","cat":"Grading, demo & erosion control","def":"Measures that keep soil from washing or blowing away, like hydroseed, blankets and fiber rolls. Temporary ones protect during work; permanent ones stay.","mod":7},
  {"term":"Erosion control blanket","abbr":"ECB","also":"erosion control mat","cat":"Grading, demo & erosion control","def":"A rolled blanket of straw, coconut or jute fiber pinned over slopes to hold soil until plants grow.","mod":7},
  {"term":"Erosion control plan","abbr":"EC","cat":"Plans & drawings","def":"Sheets showing permanent erosion control like hydroseed, compost and blankets.","mod":4},
  {"term":"Erosion control seeding","abbr":"","cat":"Grading, demo & erosion control","def":"Seeding slopes with a mix chosen to hold soil, often native grasses and wildflowers.","mod":7},
  {"term":"Escalation","abbr":"","cat":"Money & estimating","def":"An amount added for prices rising between bid day and when you buy. Important on long jobs and plant material.","mod":8},
  {"term":"Estimate","abbr":"","cat":"Money & estimating","def":"Your calculation of what a job will cost, before markup.","mod":1},
  {"term":"Estimated total water use","abbr":"ETWU","cat":"Irrigation","def":"Under MWELO, the designer's estimate of a landscape's yearly water use. It must not exceed the MAWA.","mod":5},
  {"term":"Estimated vs. actual","abbr":"","also":"estimate to actual; post-job review","cat":"Money & estimating","def":"Comparing the hours and costs you estimated with what really happened, to improve the next bid.","mod":9},
  {"term":"Evapotranspiration","abbr":"ET","also":"ETo","cat":"Irrigation","def":"Water lost from soil and plants to the air. ETo is the standard rate for a reference grass; smart controllers use it to set run times.","mod":6},
  {"term":"Excavation","abbr":"","cat":"Grading, demo & erosion control","def":"Digging. Specs say how it's measured and paid.","mod":7},
  {"term":"Excavation permit","abbr":"","also":"Cal/OSHA trench permit","cat":"Public works & compliance","def":"A Cal/OSHA permit required before workers go into trenches or excavations 5 feet deep or more.","mod":9},
  {"term":"Exclusion","abbr":"","cat":"Bidding & contracts","def":"Work near your scope that you state you are not providing.","mod":13},
  {"term":"Execution","abbr":"","also":"execute the contract","cat":"Bidding & contracts","def":"Signing the contract. Public agencies give the winning bidder a set number of days to sign and send bonds and insurance.","mod":16},
  {"term":"Expansion joint","abbr":"EJ","cat":"Hardscape & site work","def":"A gap filled with soft material that lets concrete move without cracking.","mod":7},
  {"term":"Experience modification rate","abbr":"EMR","also":"experience mod; X-mod","cat":"Licensing, insurance & bonds","def":"A number based on your past workers' comp claims that multiplies your premium. 1.0 is average, lower is better. Some GCs won't hire subs above a set EMR.","mod":2},
  {"term":"Export","abbr":"","also":"haul-off; off-haul","cat":"Grading, demo & erosion control","def":"Soil or debris trucked off the site. Price trucking and dump fees.","mod":7},
  {"term":"Exposed aggregate","abbr":"","cat":"Hardscape & site work","def":"A concrete finish where the top paste is washed off to show the stones.","ex":"Caltrans 11-430674 item 105: Slope Paving (Exposed Aggregate), 380 CY.","mod":7},
  {"term":"Extension","abbr":"","also":"item total; extended price","cat":"Money & estimating","def":"Unit price times quantity. Agencies usually go by the unit price if your extension has a math error, so check both.","mod":14},
  {"term":"Extra work","abbr":"","also":"extras","cat":"Construction phrases & jargon","def":"Work outside the contract. It should be paid by change order, not done for free.","mod":16},
  {"term":"Federal Highway Administration","abbr":"FHWA","cat":"Agencies & organizations","def":"The federal agency that funds and oversees federal-aid highway projects.","mod":15},
  {"term":"Federal-aid project","abbr":"","also":"federally funded","cat":"Public works & compliance","def":"A job paid partly with federal money. Federal rules like Davis-Bacon, DBE goals and Buy America then apply.","mod":11},
  {"term":"Feet per second","abbr":"FPS","also":"ft/s","cat":"Units & measurement","def":"The speed of water in a pipe. Designers commonly keep it at or below about 5 FPS to limit water hammer.","mod":6},
  {"term":"Fertilizer","abbr":"","cat":"Planting & soil","def":"Nutrients for plants, labeled by N-P-K (nitrogen, phosphorus, potassium) percent, like 16-6-8.","mod":7},
  {"term":"Fiber roll","abbr":"","also":"straw wattle; wattle","cat":"Grading, demo & erosion control","def":"A tube of straw or fiber staked along a slope or edge to slow runoff and trap sediment.","ex":"Caltrans 11-428704 item 15: Temporary Fiber Roll, 7,190 LF.","mod":7},
  {"term":"FICA","abbr":"FICA","also":"Social Security and Medicare tax","cat":"Money & estimating","def":"Federal payroll taxes. The employer pays 7.65% of wages: 6.2% Social Security (up to a yearly wage limit) plus 1.45% Medicare.","mod":9},
  {"term":"Field order","abbr":"FO","cat":"Bidding & contracts","def":"A written order from the owner's field staff for a small change. On City of San Diego jobs, field orders are paid from a “Field Orders” bid item, within set limits.","ex":"City of San Diego K-24-1952: up to $10,000 per field order on contracts under $1,000,001.","mod":16},
  {"term":"Fill","abbr":"","cat":"Grading, demo & erosion control","def":"Soil placed to raise the grade, compacted in layers.","mod":7},
  {"term":"Filter","abbr":"","also":"screen filter; disc filter","cat":"Irrigation","def":"A device that catches dirt before it clogs drip emitters.","mod":6},
  {"term":"Final acceptance","abbr":"","also":"acceptance","cat":"Bidding & contracts","def":"The owner's formal approval that all work is complete. On landscape jobs this usually comes after plant establishment.","mod":16},
  {"term":"Final payment","abbr":"","cat":"Bidding & contracts","def":"The last payment, including retention, released after acceptance and closeout paperwork.","mod":16},
  {"term":"Fine grading","abbr":"","also":"finish grading","cat":"Grading, demo & erosion control","def":"Final shaping of the soil surface to exact grades before planting or paving.","mod":7},
  {"term":"Finished floor","abbr":"FF","cat":"Plans & drawings","def":"Elevation of the building floor. Planting and grades must stay below it so water drains away.","mod":4},
  {"term":"Finished grade","abbr":"FG","cat":"Plans & drawings","def":"The final ground surface after all grading and soil prep, before mulch unless the plans say otherwise.","mod":7},
  {"term":"Finished surface","abbr":"FS","cat":"Plans & drawings","def":"The final top of paving or other surface, often given as an elevation. On irrigation plans, FS may mean flow sensor instead, so check the legend.","mod":4},
  {"term":"Fixed cost","abbr":"","cat":"Money & estimating","def":"A cost that stays the same no matter how much work you do, like office rent.","mod":10},
  {"term":"Fixture (sales tax)","abbr":"","cat":"Money & estimating","def":"For sales tax, an item that keeps its identity after installation. CDTFA generally treats plants, trees and shrubs as fixtures, which makes the landscape contractor the retailer of them (Regulation 1521).","mod":8},
  {"term":"Flat","abbr":"FLAT","cat":"Planting & soil","def":"A shallow tray of small plants or rooted cuttings, sold by the flat. Groundcover is often planted from flats. Caltrans calls this Plant Group F.","mod":7},
  {"term":"Flatwork","abbr":"","cat":"Hardscape & site work","def":"Concrete on the ground, like walks, pads and patios.","mod":7},
  {"term":"Float","abbr":"","also":"slack","cat":"Construction phrases & jargon","def":"How long a task can slip without moving the job's finish date.","mod":16},
  {"term":"Flow line","abbr":"FL","cat":"Plans & drawings","def":"The low line where water flows, like the bottom of a gutter or swale.","mod":4},
  {"term":"Flow sensor","abbr":"FS","also":"flow meter","cat":"Irrigation","def":"A device on the mainline that measures flow so the controller can shut down on a break.","ex":"Caltrans 11-428704 item 50: Flow Sensor, 4 EA.","mod":6},
  {"term":"Flow-down clause","abbr":"","also":"flow-down","cat":"Bidding & contracts","def":"A subcontract clause that binds you to the GC the same way the GC is bound to the owner. Read the prime contract terms that flow down to you.","mod":16},
  {"term":"Flushing","abbr":"","also":"flush","cat":"Irrigation","def":"Running water through new pipe before installing heads or emitters, to clear dirt.","mod":6},
  {"term":"Force account","abbr":"","cat":"Bidding & contracts","def":"Agency term for paying extra work at actual cost of labor, equipment and materials plus set markups, when no price is agreed.","mod":16},
  {"term":"Freight","abbr":"","also":"delivery charge","cat":"Money & estimating","def":"The cost to get material to the job. Ask if a quote is “delivered” or “will call.”","mod":8},
  {"term":"French drain","abbr":"","cat":"Hardscape & site work","def":"A gravel trench, often with perforated pipe, that collects and carries away groundwater.","mod":7},
  {"term":"Fringe","abbr":"","also":"fringe benefits","cat":"Public works & compliance","def":"The benefit part of a prevailing wage rate, paid to plans or as cash to the worker.","mod":9},
  {"term":"Front end","abbr":"","also":"front-end documents","cat":"Specifications","def":"Divisions 00 and 01: bid forms, contract, conditions and general requirements. Read it every time; it holds bonds, insurance, LDs and payment terms.","mod":5},
  {"term":"Front-loading","abbr":"","cat":"Money & estimating","def":"Putting extra money in early items to get paid sooner. Owners watch for it in schedules of values and bids.","mod":10},
  {"term":"Funny pipe","abbr":"","also":"swing pipe; flex pipe","cat":"Irrigation","def":"Field slang for small flexible tubing used to connect heads to laterals.","mod":6},
  {"term":"Furnish and install","abbr":"F&I","also":"supply and install","cat":"Bidding & contracts","def":"You provide the material and install it. Compare “furnish only” and “install only.”","mod":13},
  {"term":"Furnish only","abbr":"","also":"supply only","cat":"Bidding & contracts","def":"You provide the material and someone else installs it.","mod":13},
  {"term":"Gallon","abbr":"GAL","also":"gal","cat":"Units & measurement","def":"A unit of liquid volume. In plants, “1 GAL” or “#1” means a container size, not exact gallons.","mod":0},
  {"term":"Gallons per hour","abbr":"GPH","also":"gph","cat":"Units & measurement","def":"Flow rate used for drip emitters and inline drip tubing.","mod":6},
  {"term":"Gallons per minute","abbr":"GPM","also":"gpm","cat":"Units & measurement","def":"Flow rate used for sprinklers, valves, meters and zones.","mod":6},
  {"term":"Gasketed pipe","abbr":"","also":"ring-tite; bell and spigot","cat":"Irrigation","def":"Pipe joined with a rubber gasket instead of glue. Usually needs thrust blocks at fittings.","mod":6},
  {"term":"Gate valve","abbr":"GV","cat":"Irrigation","def":"A shutoff valve with a gate that slides down to stop flow. Used to isolate sections of mainline.","ex":"Caltrans 11-428704 item 56: 4\" Gate Valve, 7 EA.","mod":6},
  {"term":"Gear-driven rotor","abbr":"","also":"rotor","cat":"Irrigation","def":"A sprinkler that turns a single stream slowly to cover large areas.","ex":"Caltrans 11-428704 item 52: Riser Sprinkler Assembly (Gear Driven), 15 EA.","mod":6},
  {"term":"General conditions (contract)","abbr":"","also":"general provisions","cat":"Specifications","def":"The standard legal terms of the contract: changes, payment, claims, insurance and termination. (A GC's “general conditions” cost is different; see that entry.)","mod":5},
  {"term":"General conditions (cost)","abbr":"GCs","also":"jobsite overhead; general requirements cost","cat":"Money & estimating","def":"A GC's job-related costs that aren't in any one trade: supervision, trailer, toilets, fencing, cleanup. On some bid forms it's a separate line.","mod":10},
  {"term": "General contractor", "abbr": "GC", "cat": "Bidding & contracts", "def": "The contractor that holds the contract with the owner and hires and manages the subcontractors. On building and private site work, the GC is usually your customer.", "mod": 1},
  {"term":"General indemnity agreement","abbr":"GIA","also":"indemnity agreement","cat":"Licensing, insurance & bonds","def":"The agreement you and usually your company owners sign with a surety, promising to pay back any loss. Owners often sign personally.","mod":2},
  {"term":"General notes","abbr":"","also":"notes","cat":"Plans & drawings","def":"Written notes on the plans that apply to the whole sheet or set. They often hold costly requirements.","mod":4},
  {"term":"General prevailing wage determination","abbr":"","also":"wage determination","cat":"Public works & compliance","def":"DIR's published wage rates for each craft and area. The determination in effect when the job is advertised applies to that job.","mod":11},
  {"term":"Girdling root","abbr":"","cat":"Planting & soil","def":"A root circling the trunk that can choke the tree later. Cut them at planting.","mod":7},
  {"term":"Go / no-go","abbr":"","also":"bid / no-bid","cat":"Bidding & contracts","def":"The decision whether a job is worth the time to estimate.","mod":3},
  {"term":"Good faith effort","abbr":"GFE","cat":"Public works & compliance","def":"Proof you tried hard to meet a DBE or SLBE goal when you fell short: outreach, follow-ups, quotes and reasons for rejections.","mod":14},
  {"term":"Grade break","abbr":"GB","cat":"Plans & drawings","def":"Where a slope changes direction or steepness.","mod":4},
  {"term":"Grading","abbr":"","cat":"Grading, demo & erosion control","def":"Shaping the ground to the elevations on the plans.","mod":7},
  {"term":"Grading permit","abbr":"","cat":"Grading, demo & erosion control","def":"A city or county permit for moving soil. Often needed for larger grading; the owner usually gets it.","mod":7},
  {"term":"Graphic scale","abbr":"","also":"scale bar","cat":"Plans & drawings","def":"A ruler drawn on the sheet that stays true when the sheet is printed smaller.","mod":4},
  {"term":"Gravel bag","abbr":"","also":"sandbag","cat":"Grading, demo & erosion control","def":"A bag of gravel used for check dams, inlet protection and barriers.","mod":7},
  {"term":"Green waste","abbr":"","cat":"Grading, demo & erosion control","def":"Plant clippings, branches and roots. Recyclers often take it for less than mixed debris.","mod":7},
  {"term":"Greenbook","abbr":"SSPWC","also":"Standard Specifications for Public Works Construction","cat":"Specifications","def":"The standard spec book used by many Southern California cities and agencies. Each job adds its own changes.","mod":5},
  {"term":"Gross margin","abbr":"","also":"gross profit margin","cat":"Money & estimating","def":"Price minus job cost, as a percent of price.","mod":10},
  {"term":"Gross profit","abbr":"GP","cat":"Money & estimating","def":"Price minus direct job costs, in dollars. It has to pay company overhead and leave profit.","mod":10},
  {"term":"Groundcover","abbr":"GC","cat":"Planting & soil","def":"Low plants that spread to cover the ground, planted at a set spacing or from flats.","mod":7},
  {"term":"Guaranteed maximum price","abbr":"GMP","cat":"Bidding & contracts","def":"A price cap in a contract. Costs above the cap are the contractor's risk; savings below it may be shared.","mod":1},
  {"term":"Guying","abbr":"","also":"guy wires","cat":"Planting & soil","def":"Holding a large tree upright with cables anchored to the ground.","mod":7},
  {"term":"Gypsum","abbr":"","cat":"Planting & soil","def":"A soil amendment that helps clay and salty soils drain.","mod":7},
  {"term":"Hand dig","abbr":"","also":"hand excavation","cat":"Grading, demo & erosion control","def":"Digging by shovel near utilities, roots or tight spaces. Much slower than machine digging, so price it separately.","mod":9},
  {"term":"Hard bid","abbr":"","also":"sealed bid; competitive bid","cat":"Bidding & contracts","def":"A job won on price alone through sealed bids. Most public work is hard bid.","mod":1},
  {"term":"Hatch","abbr":"","also":"hatch pattern","cat":"Plans & drawings","def":"A fill pattern showing an area, like turf, groundcover or mulch. The legend says what each hatch means.","mod":4},
  {"term":"Haul route","abbr":"","cat":"Grading, demo & erosion control","def":"The roads trucks must use to and from the site. Agencies may restrict them.","mod":12},
  {"term":"Heat illness prevention","abbr":"","cat":"Public works & compliance","def":"Cal/OSHA rules for outdoor work in heat: fresh water, shade, rest and training. Shade must be up when it's over 80°F.","mod":9},
  {"term":"Height and spread","abbr":"H x W","cat":"Planting & soil","def":"A plant's size by height and width. Specs may require a minimum along with the container size.","mod":7},
  {"term":"High point","abbr":"HP","cat":"Plans & drawings","def":"The highest spot on a grade, where water flows away.","mod":4},
  {"term":"High-density polyethylene","abbr":"HDPE","also":"poly; PE","cat":"Irrigation","def":"A tough, flexible plastic pipe. Used for some water lines and for conduit and sleeves.","ex":"Caltrans 11-428704 item 67: 10\" Corrugated High Density Polyethylene Pipe Conduit, 370 LF.","mod":6},
  {"term":"Highway planting","abbr":"","cat":"Planting & soil","def":"Caltrans's name for landscape planting and irrigation work along state highways, often done as its own project after the road is built.","mod":15},
  {"term":"Hit rate","abbr":"","also":"win rate","cat":"Money & estimating","def":"Bids won divided by bids sent, as a percent.","mod":10},
  {"term":"Hose bib","abbr":"HB","cat":"Irrigation","def":"A threaded faucet for a hose.","mod":6},
  {"term":"Hot mix asphalt","abbr":"HMA","also":"asphalt; AC","cat":"Hardscape & site work","def":"Asphalt paving placed hot and rolled, paid by the ton.","ex":"Caltrans 11-422004 item 46: Hot Mix Asphalt (Type A), 20 TON.","mod":15},
  {"term":"Hour","abbr":"HR","cat":"Units & measurement","def":"A pay unit for items paid by the hour.","ex":"Caltrans 11-428704 item 18: Manage Solid Waste Generated by the Public, 300 HR.","mod":0},
  {"term":"Hydromulch","abbr":"","cat":"Grading, demo & erosion control","def":"Wood or paper fiber mulch sprayed on with water, often with seed, to protect soil.","mod":7},
  {"term":"Hydroseed","abbr":"","also":"hydroseeding","cat":"Grading, demo & erosion control","def":"Seed, fiber mulch, tackifier and fertilizer sprayed on as a slurry. Priced per SF or acre.","ex":"Caltrans 11-431064 item 63: Hydroseed, 797,000 SQFT.","mod":7},
  {"term":"Hydrostatic test","abbr":"","also":"pressure test","cat":"Irrigation","def":"Filling a new mainline with water and holding pressure for a set time to prove it doesn't leak. Specs set the pressure and time.","mod":6},
  {"term":"Hydrozone","abbr":"","cat":"Irrigation","def":"An area of plants with similar water needs, watered by the same valve.","mod":6},
  {"term":"Import","abbr":"","also":"import fill","cat":"Grading, demo & erosion control","def":"Soil brought onto the site from somewhere else. Specs often require testing before use.","mod":7},
  {"term":"Imported planting soil","abbr":"","also":"import soil; planting mix","cat":"Planting & soil","def":"Soil brought in for planting areas. Price it by the CY, plus trucking and spreading.","mod":7},
  {"term":"Inches per hour","abbr":"in/hr","also":"precipitation rate","cat":"Units & measurement","def":"How fast a sprinkler zone puts water on the ground. Sprays put down water faster than rotors.","mod":6},
  {"term":"Included in the payment for","abbr":"","also":"no separate payment; incidental","cat":"Specifications","def":"Spec wording meaning the work has no pay item of its own. Its cost goes into another item's price.","mod":5},
  {"term":"Inclusion","abbr":"","cat":"Bidding & contracts","def":"An item you state you are providing, to remove doubt.","mod":13},
  {"term":"Indemnity","abbr":"","also":"hold harmless; indemnification","cat":"Bidding & contracts","def":"A promise to defend and pay for certain claims. Subcontracts usually make you protect the GC and owner from claims caused by your work. California law (Civil Code 2782) limits how far some of these clauses can go.","mod":16},
  {"term":"Indirect cost","abbr":"","cat":"Money & estimating","def":"Costs that keep the job or company running but aren't part of one installed item.","mod":10},
  {"term":"Injury and Illness Prevention Program","abbr":"IIPP","cat":"Public works & compliance","def":"A written safety program every California employer must have and follow (8 CCR 3203).","mod":2},
  {"term":"Inland marine","abbr":"","also":"equipment floater","cat":"Licensing, insurance & bonds","def":"Insurance for tools and equipment that move between jobs, and for materials in transit.","mod":9},
  {"term":"Inlet protection","abbr":"","also":"drain inlet protection","cat":"Grading, demo & erosion control","def":"Filters or barriers around storm drain inlets that catch sediment.","ex":"Caltrans 11-428704 item 14: Temporary Drainage Inlet Protection, 2 EA.","mod":7},
  {"term":"Inline drip tubing","abbr":"","also":"dripline; emitter tubing","cat":"Irrigation","def":"Tubing with emitters built in at a set spacing, laid in rows across a planting area.","mod":6},
  {"term":"Inspector","abbr":"","cat":"Bidding & contracts","def":"The owner's or agency's person who checks your work in the field. Get inspections before you cover anything up.","mod":16},
  {"term":"Install only","abbr":"","cat":"Bidding & contracts","def":"You install material someone else provides. Agree on who handles delivery, storage, damage and warranty.","mod":13},
  {"term":"Instructions to bidders","abbr":"","cat":"Bidding & contracts","def":"The part of the bid documents that tells you how to fill out, sign and deliver the bid, and what gets a bid rejected.","mod":14},
  {"term":"Insurance certificate","abbr":"COI","also":"certificate of insurance","cat":"Licensing, insurance & bonds","def":"A form, usually the ACORD 25, from your insurance broker showing your policies and limits. GCs require one before you start.","mod":2},
  {"term":"International Society of Arboriculture","abbr":"ISA","cat":"Agencies & organizations","def":"The group that certifies arborists and publishes tree care standards. Specs may require an ISA Certified Arborist.","mod":7},
  {"term":"Invert","abbr":"INV","also":"IE; invert elevation","cat":"Plans & drawings","def":"The inside bottom of a pipe or drain, given as an elevation.","mod":4},
  {"term":"Invitation for bids","abbr":"IFB","cat":"Bidding & contracts","def":"A formal request for sealed bids, used by many public agencies. Same idea as a notice inviting bids.","mod":3},
  {"term":"Invitation to bid","abbr":"ITB","also":"bid invitation; bid invite","cat":"Bidding & contracts","def":"A message from an owner or GC asking you to bid a project, with the due date and a link to the documents.","mod":3},
  {"term":"Iron sulfate","abbr":"","cat":"Planting & soil","def":"A soil additive that adds iron and lowers pH.","ex":"Caltrans 11-428704 item 22: Iron Sulfate (LB), 230 LB.","mod":7},
  {"term":"Irrigation Association","abbr":"IA","cat":"Agencies & organizations","def":"The national irrigation industry group. It offers certifications like Certified Irrigation Contractor and Certified Landscape Irrigation Auditor.","mod":6},
  {"term":"Irrigation audit","abbr":"","cat":"Irrigation","def":"A test of a sprinkler system's pressure, coverage and uniformity, often required by MWELO on larger new landscapes.","mod":6},
  {"term":"Irrigation details","abbr":"ID","cat":"Plans & drawings","def":"The sheets of irrigation installation details.","ex":"Caltrans 11-428704: ID-1 to ID-6.","mod":4},
  {"term":"Irrigation plan","abbr":"IP","also":"I sheets","cat":"Plans & drawings","def":"The sheets showing the irrigation layout. Caltrans uses IP sheet codes.","ex":"Caltrans 11-428704: IP-1 to IP-7.","mod":4},
  {"term":"Irrigation quantities","abbr":"IQ","cat":"Plans & drawings","def":"Caltrans sheets listing irrigation quantities.","ex":"Caltrans 11-428704: IQ-1 and IQ-2 (IQ-1 replaced by Addendum 1).","mod":15},
  {"term":"Irrigation removal plan","abbr":"IR","cat":"Plans & drawings","def":"Caltrans sheets showing existing irrigation to remove, salvage or keep.","ex":"Caltrans 11-428704: IR-1 to IR-7.","mod":4},
  {"term":"Isolation valve","abbr":"","also":"shutoff valve","cat":"Irrigation","def":"Any valve used to shut off part of the system for repair, like a gate or ball valve.","mod":6},
  {"term":"Job cost","abbr":"","also":"job costing","cat":"Money & estimating","def":"Tracking the actual hours and costs on a job against the estimate.","mod":16},
  {"term":"Job hazard analysis","abbr":"JHA","also":"job safety analysis; JSA","cat":"Public works & compliance","def":"A written list of the steps in a task, the hazards in each step and how to control them. Caltrans requires them before each work activity.","mod":15},
  {"term":"Job overhead","abbr":"","also":"field overhead","cat":"Money & estimating","def":"Indirect costs caused by one job: supervision, trucks, temporary facilities, permits.","mod":10},
  {"term":"Job walk","abbr":"","also":"site walk; walk the job","cat":"Bidding & contracts","def":"A visit to the project site during bidding to see conditions the plans don't show.","mod":12},
  {"term":"Joint check","abbr":"","also":"joint check agreement","cat":"Bidding & contracts","def":"A check payable to both you and your supplier, so the supplier knows it will be paid.","mod":8},
  {"term":"Joint venture","abbr":"JV","cat":"Bidding & contracts","def":"Two or more companies teaming up to bid and build one job, sharing risk and profit under a written agreement.","mod":14},
  {"term":"Journeyman","abbr":"","also":"journey-level","cat":"Public works & compliance","def":"A fully qualified worker in a craft, paid the full prevailing rate.","mod":11},
  {"term":"Keynote","abbr":"","cat":"Plans & drawings","def":"A number or letter tag on the plan explained in a list on the same sheet.","mod":4},
  {"term":"Labor and material","abbr":"L&M","cat":"Money & estimating","def":"A price that includes both labor and material. Compare “labor only” and “material only.”","mod":13},
  {"term":"Labor burden","abbr":"","also":"burden","cat":"Money & estimating","def":"Payroll taxes, workers' comp, insurance and benefits added on top of wages.","mod":9},
  {"term":"Labor Commissioner","abbr":"","also":"DLSE","cat":"Agencies & organizations","def":"The state office within DIR that enforces wage laws, including prevailing wage on public works.","mod":11},
  {"term":"Labor compliance program","abbr":"LCP","cat":"Public works & compliance","def":"An agency's program for checking prevailing wage compliance on its jobs.","mod":11},
  {"term":"Labor hour","abbr":"LH","also":"man-hour; MH; work hour","cat":"Money & estimating","def":"One worker working one hour. Production rates are often in labor hours per unit.","mod":9},
  {"term":"Landscape architect","abbr":"LA","cat":"Bidding & contracts","def":"The licensed designer of the landscape and irrigation who also writes the landscape specs and reviews your submittals.","mod":1},
  {"term":"Landscape fabric","abbr":"","also":"weed fabric; filter fabric","cat":"Planting & soil","def":"A cloth laid under rock or mulch to slow weeds or keep soil layers apart.","mod":7},
  {"term":"Landscape sheets","abbr":"L","cat":"Plans & drawings","def":"On private and city plan sets, the landscape sheets, often split into L (planting), LI or I (irrigation) and LD (details).","mod":4},
  {"term":"Lane closure","abbr":"","also":"closure","cat":"Construction phrases & jargon","def":"Closing a traffic lane so you can work, allowed only during set hours.","ex":"Caltrans uses its Lane Closure System to request and report closures.","mod":15},
  {"term":"Lane Closure System","abbr":"LCS","cat":"Construction phrases & jargon","def":"Caltrans's online system for requesting and reporting lane closures.","mod":15},
  {"term":"Late number","abbr":"","cat":"Construction phrases & jargon","def":"A sub price that arrives in the last hour before bids are due. GCs get many sub numbers late on bid day, so they're ready to plug.","mod":14},
  {"term":"Lateral","abbr":"","also":"lateral line","cat":"Irrigation","def":"Pipe downstream of a valve. It is only pressurized when the zone runs.","mod":6},
  {"term":"LCPtracker","abbr":"","cat":"Public works & compliance","def":"The online certified payroll system Caltrans uses.","ex":"Caltrans 11-428704 special provisions require certified payroll through LCPtracker Pro.","mod":11},
  {"term":"Lead compliance plan","abbr":"","cat":"Public works & compliance","def":"A Caltrans-required plan for protecting workers from lead in soil or paint.","ex":"Caltrans 11-428704 item 1: Lead Compliance Plan, LS.","mod":15},
  {"term":"Lead time","abbr":"","cat":"Money & estimating","def":"Time from order to delivery. Large boxed trees, controllers and backflow parts can have long lead times.","mod":8},
  {"term":"Legend","abbr":"","also":"key","cat":"Plans & drawings","def":"The table explaining every symbol and hatch on the plans.","mod":4},
  {"term":"Letter of intent","abbr":"LOI","cat":"Bidding & contracts","def":"A GC's written notice that it plans to subcontract with you. It is not a full contract. Don't order long-lead material on an LOI alone unless it says you may.","mod":16},
  {"term":"License bond","abbr":"","also":"contractor's license bond","cat":"Licensing, insurance & bonds","def":"A $25,000 bond every California licensed contractor must keep on file with CSLB (since January 1, 2023).","mod":2},
  {"term":"Limited specialty","abbr":"C-61","also":"C-61","cat":"Licensing, insurance & bonds","def":"CSLB's catch-all class for narrow trades that don't fit another C license, tracked with “D” subcategories.","mod":2},
  {"term":"Line voltage","abbr":"","also":"120V","cat":"Hardscape & site work","def":"Standard building power, 120 volts or more. Work on it usually needs a C-10 electrical contractor.","mod":7},
  {"term":"Linear foot","abbr":"LF","also":"lin ft; foot","cat":"Units & measurement","def":"A pay unit for length: pipe, edging, curb, fence.","ex":"Caltrans 11-428704 item 63: 4\" Plastic Pipe (Class 315) (Supply Line), 7,493 LF.","mod":0},
  {"term":"Liner","abbr":"","cat":"Planting & soil","def":"A young plant in a small container, usually grown on into bigger sizes. Caltrans calls this Plant Group M.","mod":7},
  {"term":"Liquidated damages","abbr":"LD","also":"LDs","cat":"Bidding & contracts","def":"A set dollar amount per day you finish late, written into the contract and taken from your payment.","ex":"Example: at $1,500 a day, two weeks late costs $21,000. On Caltrans jobs the daily rate is in Standard Specifications section 8-1.10.","mod":3},
  {"term":"List price","abbr":"","also":"retail price","cat":"Money & estimating","def":"The published price before any discount.","mod":8},
  {"term":"Look-ahead schedule","abbr":"","also":"3-week look-ahead","cat":"Construction phrases & jargon","def":"A short schedule of the next few weeks of work, updated every week in job meetings.","mod":16},
  {"term":"Loose cubic yard","abbr":"LCY","also":"loose yards","cat":"Units & measurement","def":"Soil measured after digging, when it has fluffed up. Trucks haul loose yards.","mod":0},
  {"term":"Low bidder","abbr":"","also":"low bid; low man","cat":"Construction phrases & jargon","def":"The bidder with the lowest price. “Low man” is field slang for the same thing.","mod":14},
  {"term":"Low point","abbr":"LP","cat":"Plans & drawings","def":"The lowest spot on a grade, where water collects. Usually needs a drain.","mod":4},
  {"term":"Low-ball","abbr":"","cat":"Construction phrases & jargon","def":"Bidding a price that's too low to make money, sometimes on purpose to win.","mod":10},
  {"term":"Low-voltage lighting","abbr":"LV","also":"landscape lighting","cat":"Hardscape & site work","def":"Outdoor lighting run at 12 or 24 volts through a transformer. Often within landscape scope; line-voltage power to the transformer may need an electrician.","mod":7},
  {"term":"Lowest responsive, responsible bidder","abbr":"","cat":"Bidding & contracts","def":"The standard most public agencies use to award: the lowest price from a bid that followed the rules, from a bidder able to do the work.","mod":14},
  {"term":"Lt / Rt","abbr":"Lt; Rt","also":"left; right","cat":"Plans & drawings","def":"Left or right of the centerline, looking up-station.","mod":4},
  {"term":"Lump sum","abbr":"LS","cat":"Units & measurement","def":"One price for a whole item, no matter the quantity. Your takeoff still has to cover everything in it.","ex":"Caltrans 11-428704 item 30: Plant Establishment Work, LS.","mod":14},
  {"term":"Lump sum contract","abbr":"","also":"stipulated sum; fixed price","cat":"Bidding & contracts","def":"One total price for all the work. Most private GC subcontracts are lump sum.","mod":1},
  {"term":"M","abbr":"M","also":"thousand","cat":"Units & measurement","def":"Roman numeral for 1,000 in some units, like MBF (thousand board feet) or MSF (thousand square feet).","mod":0},
  {"term":"Mainline","abbr":"","also":"supply line; main","cat":"Irrigation","def":"Pipe from the POC to the valves that is always under pressure. Caltrans calls it supply line.","ex":"Caltrans 11-428704 items 57 to 63: plastic pipe (supply line), 1\" to 4\".","mod":6},
  {"term":"Maintain existing planted areas","abbr":"MEPA","cat":"Planting & soil","def":"Caltrans work to water, weed and care for existing landscape inside the job during construction.","ex":"Caltrans 11-428704 item 29: Maintain Existing Planted Areas, LS.","mod":15},
  {"term":"Maintenance bond","abbr":"","also":"warranty bond","cat":"Licensing, insurance & bonds","def":"A bond guaranteeing you'll fix defects during the warranty or maintenance period.","mod":16},
  {"term":"Maintenance period","abbr":"","also":"maintenance and monitoring period","cat":"Bidding & contracts","def":"Time after installation when you keep caring for the landscape (watering, weeding, mowing, replacing plants) before the owner takes over. The specs set how long and what work is included.","mod":16},
  {"term":"Manage solid waste generated by the public","abbr":"","cat":"Grading, demo & erosion control","def":"Caltrans item paying by the hour to pick up trash left by the public in the work area.","ex":"Caltrans 11-428704 item 18: Manage Solid Waste Generated by the Public, 300 HR.","mod":15},
  {"term":"Mandatory pre-bid","abbr":"","also":"mandatory job walk","cat":"Bidding & contracts","def":"A meeting you must attend and sign in at to be allowed to bid.","mod":12},
  {"term":"Manifold","abbr":"","also":"valve manifold","cat":"Irrigation","def":"A group of valves piped together at one spot.","mod":6},
  {"term":"Manufacturer","abbr":"MFR","also":"MFG","cat":"Plans & drawings","def":"The company that makes a product. Plans list maker, model and options in the schedules.","mod":6},
  {"term":"Margin","abbr":"","also":"profit margin","cat":"Money & estimating","def":"Profit as a percent of the selling price. A 20% markup on cost equals a 16.7% margin.","mod":10},
  {"term":"Markup","abbr":"","cat":"Money & estimating","def":"Profit, or overhead and profit, as a percent added to cost. Cost $10,000 + 20% markup = $12,000 price.","mod":10},
  {"term":"Master valve","abbr":"MV","cat":"Irrigation","def":"A valve near the POC that keeps the mainline closed when no zone is running.","ex":"Caltrans 11-428704 item 39: 3\" Remote Control Valve (Master) (Two-Wire), 1 EA.","mod":6},
  {"term":"MasterFormat","abbr":"","also":"CSI MasterFormat","cat":"Specifications","def":"The standard numbering system for project manual specs, made by CSI. Landscape is in Division 32.","mod":5},
  {"term":"Match line","abbr":"ML","cat":"Plans & drawings","def":"A line where one plan sheet continues on another. Don't count items on both sides twice.","mod":4},
  {"term":"Matched precipitation","abbr":"MPR","cat":"Irrigation","def":"Heads and nozzles that put down water at the same rate no matter the arc, so a zone waters evenly.","mod":6},
  {"term":"Material quote","abbr":"","also":"supplier quote","cat":"Money & estimating","def":"A supplier's written price for your job's material list. Check what's included, the tax, freight and the expiration date.","mod":8},
  {"term":"Maximum applied water allowance","abbr":"MAWA","cat":"Irrigation","def":"Under MWELO, the yearly water budget for a landscape. The design's estimated use must stay under it.","mod":5},
  {"term":"Maximum dry density","abbr":"","also":"Proctor","cat":"Grading, demo & erosion control","def":"The densest a soil can be packed in a lab test, at its best moisture. Field compaction is measured against it.","mod":7},
  {"term":"Measurement and payment","abbr":"","also":"basis of payment","cat":"Specifications","def":"The part of a spec that says how each item is measured and what the price includes. Read it before pricing any unit price item.","mod":5},
  {"term":"Mechanics lien","abbr":"","also":"mechanic's lien","cat":"Bidding & contracts","def":"A claim against private property for unpaid work or materials. Strict notice and filing deadlines apply.","mod":16},
  {"term":"Minor concrete","abbr":"","cat":"Hardscape & site work","def":"Caltrans's term for small concrete work like curbs, walks, pads and mow strips.","ex":"Caltrans 11-422004 item 52: Minor Concrete (Miscellaneous Construction), 19 CY.","mod":15},
  {"term":"Mitigated negative declaration","abbr":"MND","cat":"Public works & compliance","def":"A CEQA finding that a project's impacts will be small if certain steps are taken. Those steps can become construction rules.","ex":"City of San Diego K-24-1952 includes its MND as an appendix.","mod":3},
  {"term":"Mobilization","abbr":"MOB","also":"mob","cat":"Money & estimating","def":"Moving crews, equipment and offices to the job and setting up. Caltrans pays it as a lump sum bid item, in steps as work progresses.","ex":"Caltrans 11-428704 item 70: Mobilization, LS.","mod":9},
  {"term":"Mockup","abbr":"","cat":"Specifications","def":"A small section built on site for approval, like a stretch of DG path or boulder setting. Price the labor and material.","mod":5},
  {"term":"Model Water Efficient Landscape Ordinance","abbr":"MWELO","cat":"Public works & compliance","def":"California's water-saving rules for new and rebuilt landscapes, adopted by cities and counties. Covers water budgets, plant water use, irrigation equipment and soil. Generally applies to new landscapes of 500 SF or more that need a permit or plan check.","mod":5},
  {"term":"Moisture conditioning","abbr":"","cat":"Grading, demo & erosion control","def":"Adding water to soil, or drying it, to get the right moisture for compaction.","mod":7},
  {"term":"Money left on the table","abbr":"","also":"left on the table","cat":"Construction phrases & jargon","def":"The gap between the low bid and the second bid. The winner could have bid that much higher and still won.","ex":"Caltrans 11-428704: winner $1,176,120.00, second $1,179,705.30, so only $3,585.30 was left on the table.","mod":15},
  {"term":"Move-in/move-out","abbr":"","also":"MIMO","cat":"Grading, demo & erosion control","def":"Caltrans item paying each time an erosion control crew and equipment come to the site.","ex":"Caltrans 11-422004 item 39: Move-In/Move-Out (Erosion Control), 3 EA.","mod":15},
  {"term":"Mow curb","abbr":"","also":"mow strip; mowing strip","cat":"Hardscape & site work","def":"A narrow concrete band at the edge of turf so mowers can trim clean.","mod":7},
  {"term":"Mulch","abbr":"","cat":"Planting & soil","def":"A layer over the soil, like wood chips, bark or rock, to hold moisture and stop weeds.","mod":7},
  {"term":"Multi-trunk","abbr":"MT","also":"multi","cat":"Planting & soil","def":"A tree with several main trunks. Standard (STD) means a single trunk.","mod":7},
  {"term":"National pipe thread","abbr":"NPT","also":"MPT; FPT; MIPT; FIPT","cat":"Irrigation","def":"The standard tapered thread on U.S. pipe fittings. MPT or MIPT is male (outside) thread; FPT or FIPT is female (inside) thread.","mod":6},
  {"term":"National Pollutant Discharge Elimination System","abbr":"NPDES","cat":"Public works & compliance","def":"The federal Clean Water Act permit program. California's construction storm water permit is an NPDES permit.","mod":7},
  {"term":"Negotiated work","abbr":"","also":"negotiated bid","cat":"Bidding & contracts","def":"A job priced by working it out with one owner or GC, instead of competing on sealed bids.","mod":1},
  {"term":"Net 30","abbr":"","also":"net 30 days","cat":"Money & estimating","def":"Supplier terms: pay the full invoice within 30 days of the invoice date.","mod":3},
  {"term":"Net margin","abbr":"","also":"net profit margin","cat":"Money & estimating","def":"Profit after company overhead, as a percent of price.","mod":10},
  {"term":"No-bid","abbr":"","also":"decline to bid","cat":"Construction phrases & jargon","def":"Telling a GC you won't bid a job. Always reply. It keeps you on the bid list.","mod":3},
  {"term":"Nonresponsible","abbr":"","also":"not responsible","cat":"Bidding & contracts","def":"A bidder the agency finds not able or not qualified to do the work, like one missing a needed license or registration.","mod":14},
  {"term":"Nonresponsive","abbr":"NR","also":"non-responsive","cat":"Bidding & contracts","def":"A bid that doesn't follow the bid rules, like a missing form, signature or bond. It is thrown out no matter the price.","ex":"Caltrans 11-428704 Bid Summary: the lowest price was marked “NR LATE DBE/DVBE SUBMITTAL.”","mod":14},
  {"term":"Nonstandard Special Provisions","abbr":"NSSP","cat":"Specifications","def":"Special provision paragraphs written just for one job, when no standard paragraph fits.","mod":5},
  {"term":"Normally closed","abbr":"NC","cat":"Irrigation","def":"A valve that stays shut until power opens it. Most master valves are normally closed.","mod":6},
  {"term":"North arrow","abbr":"","cat":"Plans & drawings","def":"The arrow showing which way is north on a plan sheet.","mod":4},
  {"term":"Not in contract","abbr":"NIC","cat":"Plans & drawings","def":"Shown on the plans for information only. Not part of the work.","mod":4},
  {"term":"Not to scale","abbr":"NTS","cat":"Plans & drawings","def":"The drawing isn't drawn to scale. Don't measure it; use the written dimensions.","mod":4},
  {"term":"Notice inviting bids","abbr":"NIB","also":"notice inviting sealed bids; advertisement","cat":"Bidding & contracts","def":"The public announcement of a bid, with key dates, the license needed, bond rules and where to get documents.","mod":3},
  {"term":"Notice of award","abbr":"NOA","cat":"Bidding & contracts","def":"The owner's written notice that it has awarded the contract.","mod":16},
  {"term":"Notice of completion","abbr":"NOC","cat":"Bidding & contracts","def":"A notice an owner records with the county when work is done. It shortens the deadlines to file liens and stop payment notices, so watch for it.","mod":16},
  {"term":"Notice of Intent","abbr":"NOI","cat":"Public works & compliance","def":"The filing that gets a project covered under the Construction General Permit. (In bidding, NOI can also mean notice of intent to award.)","mod":7},
  {"term":"Notice of intent to award","abbr":"NOI","cat":"Bidding & contracts","def":"A public notice that the agency plans to award to a certain bidder. Protest deadlines often start from it. In storm water work, NOI means a different thing: the notice of intent to get permit coverage.","mod":14},
  {"term":"Notice of Termination","abbr":"NOT","cat":"Public works & compliance","def":"The filing that ends a project's storm water permit coverage once the site is stable.","mod":7},
  {"term":"Notice to Bidders","abbr":"","cat":"Bidding & contracts","def":"Caltrans's name for the first pages of the special provisions. They summarize the job, bid date, license needed, goals and working days.","mod":15},
  {"term":"Notice to proceed","abbr":"NTP","cat":"Bidding & contracts","def":"The official go-ahead to start work. Contract time usually starts counting from it.","mod":1},
  {"term":"Nozzle","abbr":"","cat":"Irrigation","def":"The part of a sprinkler that shapes the spray and sets its radius and flow.","mod":6},
  {"term":"Number (your bid price)","abbr":"","also":"your number; the number","cat":"Construction phrases & jargon","def":"Slang for your bid price. “Get your number in by noon” means send your price by noon.","mod":1},
  {"term":"Number sign","abbr":"NO.","also":"#; No.","cat":"Units & measurement","def":"“No.” or “#” before a number. On plant lists, #1 and #5 mean container sizes; on rebar, #4 means 4/8 inch bar.","mod":0},
  {"term":"Nursery","abbr":"","also":"grower","cat":"Planting & soil","def":"A business that grows and sells plants. Get written quotes for availability, size and price.","mod":8},
  {"term":"Nursery inspection","abbr":"","cat":"Planting & soil","def":"A check of plant quality at the nursery before delivery, sometimes required by the specs.","mod":8},
  {"term":"Obligee","abbr":"","cat":"Licensing, insurance & bonds","def":"On a bond, the party the bond protects, like the owner, agency or GC.","mod":14},
  {"term":"Occupational Safety and Health Administration","abbr":"OSHA","cat":"Agencies & organizations","def":"The federal workplace safety agency. In California, Cal/OSHA runs the program with its own rules.","mod":2},
  {"term":"Offset","abbr":"OS","cat":"Plans & drawings","def":"Distance sideways from a centerline or line, usually left or right.","mod":4},
  {"term":"On center","abbr":"OC","also":"O.C.; o.c.","cat":"Plans & drawings","def":"Distance from the center of one item to the center of the next, like plant spacing or stake spacing.","mod":4},
  {"term":"Operate existing irrigation facilities","abbr":"","cat":"Irrigation","def":"Caltrans work to keep an existing system running during construction so plants don't die.","ex":"Caltrans 11-428704 item 33: Operate Existing Irrigation Facilities, LS.","mod":15},
  {"term":"Operating cost","abbr":"","cat":"Money & estimating","def":"Equipment cost per running hour: fuel, oil, repairs and wear parts.","mod":9},
  {"term":"Operation and maintenance manual","abbr":"O&M manual","also":"O&M","cat":"Specifications","def":"A binder or file of product data, warranties and care instructions for what you installed, given to the owner at closeout.","mod":16},
  {"term":"Optimum moisture","abbr":"","also":"optimum moisture content","cat":"Grading, demo & erosion control","def":"The moisture at which a soil packs tightest.","mod":7},
  {"term":"Or equal","abbr":"","also":"or approved equal; or equivalent","cat":"Specifications","def":"Spec words that let you offer a product equal to the named one, if the owner approves it. Price the named product unless you're sure the substitute will be accepted.","mod":5},
  {"term":"Order of precedence","abbr":"","cat":"Specifications","def":"The contract rule saying which document wins when two conflict, such as specs over plans or special provisions over standard specs.","mod":5},
  {"term":"Original ground","abbr":"OG","also":"existing grade; EG","cat":"Plans & drawings","def":"The ground surface before construction.","mod":4},
  {"term":"Other Business Enterprise","abbr":"OBE","cat":"Public works & compliance","def":"City of San Diego term for a business that isn't certified as SLBE, ELBE or another listed group. Used in City participation forms.","mod":14},
  {"term":"Overbilling","abbr":"","also":"billings in excess","cat":"Money & estimating","def":"When you've billed more than the work done is worth. It looks like cash today but you'll owe the work later.","mod":16},
  {"term":"Overexcavation","abbr":"","also":"overex","cat":"Grading, demo & erosion control","def":"Digging out more soil than needed and replacing it compacted, to fix poor soil.","mod":7},
  {"term":"Overhead","abbr":"OH","cat":"Money & estimating","def":"Costs of doing business that aren't direct job costs. See company overhead and job overhead.","mod":10},
  {"term":"Overhead and profit","abbr":"OH&P","also":"O&P","cat":"Money & estimating","def":"The markup for overhead and profit, often written as one percent on change orders.","mod":10},
  {"term":"Overhead rate","abbr":"","cat":"Money & estimating","def":"Company overhead divided by direct job costs, as a percent. Tells you how much to add to each job.","mod":10},
  {"term":"Overtime","abbr":"OT","cat":"Money & estimating","def":"Hours paid at 1.5 times or more, under California daily and weekly rules. Public work rates set their own overtime.","mod":9},
  {"term":"Owner","abbr":"","also":"client","cat":"Bidding & contracts","def":"Whoever pays for the project: a developer, business, HOA or public agency.","mod":1},
  {"term":"Owner-controlled insurance program","abbr":"OCIP","also":"wrap-up","cat":"Licensing, insurance & bonds","def":"Insurance the owner buys to cover all contractors on a job. You may need to remove your own insurance cost from your bid.","mod":2},
  {"term":"Owner-furnished, contractor-installed","abbr":"OFCI","cat":"Bidding & contracts","def":"Material the owner buys and you install. Agree on who receives, stores and warrants it.","mod":13},
  {"term":"Owner's representative","abbr":"","also":"owner's rep","cat":"Bidding & contracts","def":"The person who speaks for the owner on a job. Get written direction from this person before doing changed work.","mod":1},
  {"term":"Ownership cost","abbr":"","cat":"Money & estimating","def":"Equipment costs that happen whether the machine runs or not: payments, depreciation, insurance, storage.","mod":9},
  {"term":"Packet fertilizer","abbr":"","also":"fertilizer tablet","cat":"Planting & soil","def":"Small packets or tablets of slow-release fertilizer placed in the planting hole. Caltrans pays them by the each.","ex":"Caltrans 11-428704 item 23: Packet Fertilizer, 1,900 EA.","mod":15},
  {"term":"Palm tree","abbr":"","also":"palm","cat":"Planting & soil","def":"Palms are sold by trunk height instead of container size. Caltrans calls this Plant Group Z.","ex":"Caltrans 11-430674 item 36: Plant (Group Z) (EA), 320 EA.","mod":7},
  {"term":"Partnering","abbr":"","cat":"Bidding & contracts","def":"A structured working relationship between owner and contractor, with meetings and shared goals.","ex":"Caltrans 11-428704 special provisions call for professionally facilitated partnering on contracts over $1 million with 100 or more working days.","mod":15},
  {"term":"Pass-through","abbr":"","also":"pass-through claim","cat":"Bidding & contracts","def":"Two meanings. A pass-through claim is a sub's claim the GC passes on to the owner because the owner caused the problem. On DBE and SLBE goals, a “pass-through” is a firm that adds no real work, which doesn't count toward the goal.","mod":16},
  {"term":"Patent ambiguity","abbr":"","cat":"Bidding & contracts","def":"A conflict in the documents a careful bidder should have seen before bidding. Ask about it in an RFI; if you don't, you may be stuck with the costlier reading.","mod":12},
  {"term":"Path light","abbr":"","also":"bollard light","cat":"Hardscape & site work","def":"A short light along a walk.","mod":7},
  {"term":"Path of travel","abbr":"","also":"accessible route","cat":"Hardscape & site work","def":"The route people with disabilities use. Slopes, widths and surfaces must meet access rules, so planting can't block it.","mod":7},
  {"term":"Pavers","abbr":"","also":"unit pavers","cat":"Hardscape & site work","def":"Concrete, clay or stone units laid on sand and base to make walks and patios.","mod":7},
  {"term":"Pay application","abbr":"","also":"pay app; progress billing","cat":"Bidding & contracts","def":"Your monthly bill showing the percent complete on each line of the schedule of values.","mod":16},
  {"term":"Pay item","abbr":"","also":"bid item","cat":"Bidding & contracts","def":"A line on the bid schedule you get paid for. Work with no pay item of its own is paid inside other items.","ex":"Caltrans plans mark some work “(N)”: not a separate pay item, but it still has a cost.","mod":14},
  {"term":"Pay-if-paid","abbr":"","cat":"Bidding & contracts","def":"A clause saying you get paid only if the owner pays the GC. California courts generally won't enforce it.","mod":16},
  {"term":"Pay-when-paid","abbr":"","cat":"Bidding & contracts","def":"A clause about when you'll be paid after the GC is paid. California treats it as a timing rule; the GC must still pay you within a reasonable time.","mod":16},
  {"term":"Payment bond","abbr":"","also":"labor and material bond","cat":"Licensing, insurance & bonds","def":"A bond guaranteeing you'll pay your workers, subs and suppliers. Required on California public works contracts over $25,000 (Civil Code 9550).","mod":2},
  {"term":"Per diem","abbr":"","also":"subsistence","cat":"Money & estimating","def":"A daily allowance for meals and lodging when crews work far from home. Some prevailing wage rates require it.","mod":9},
  {"term":"Per occurrence limit","abbr":"","also":"each occurrence","cat":"Licensing, insurance & bonds","def":"The most an insurance policy pays for one accident or event.","mod":2},
  {"term":"Per project aggregate","abbr":"","also":"designated construction project aggregate","cat":"Licensing, insurance & bonds","def":"An endorsement that gives each job its own aggregate limit, so claims on one job don't use up coverage for another.","mod":2},
  {"term":"Percent slope","abbr":"%","also":"grade","cat":"Units & measurement","def":"Rise divided by run, times 100. A 2% slope rises 2 feet in 100 feet.","mod":0},
  {"term":"Performance bond","abbr":"","cat":"Licensing, insurance & bonds","def":"A bond guaranteeing you'll finish the work as the contract says. Usually 100% of the contract amount.","mod":2},
  {"term":"Performance specification","abbr":"","cat":"Specifications","def":"A spec that says what the result must be, like coverage or pressure, and leaves some choices to you.","mod":5},
  {"term":"Permeable pavers","abbr":"","cat":"Hardscape & site work","def":"Pavers set with gaps and rock base so water drains through.","mod":7},
  {"term":"Personal protective equipment","abbr":"PPE","cat":"Public works & compliance","def":"Safety gear: hard hat, safety glasses, gloves, boots, hearing protection and high-visibility vest.","mod":9},
  {"term":"Pervious concrete","abbr":"","also":"porous concrete","cat":"Hardscape & site work","def":"Concrete with open spaces that let water soak through to the ground.","ex":"Caltrans 11-422004 item 50: Pervious Concrete Pavement, 10 CY.","mod":7},
  {"term":"pH","abbr":"pH","cat":"Planting & soil","def":"How acid or alkaline soil is. 7 is neutral; many San Diego soils are above 7.","mod":7},
  {"term":"Photocell","abbr":"","also":"photo eye","cat":"Hardscape & site work","def":"A sensor that turns lights on at dusk and off at dawn.","mod":7},
  {"term":"Plan and spec","abbr":"","also":"P&S","cat":"Bidding & contracts","def":"A job where the owner's designers finished the plans and specs and you bid exactly what's drawn. The opposite of design-build.","mod":1},
  {"term":"Plan view","abbr":"","also":"plan","cat":"Plans & drawings","def":"A drawing looking straight down from above.","mod":4},
  {"term":"PlanetBids","abbr":"","cat":"Agencies & organizations","def":"An online bidding system used by the City of San Diego and many local agencies to post bids and take electronic bids.","mod":3},
  {"term":"Planholders list","abbr":"","also":"plan holders","cat":"Bidding & contracts","def":"The public list of companies that downloaded a project's bid documents. Use it to find GCs bidding a public job.","mod":3},
  {"term":"Plant establishment","abbr":"","also":"establishment","cat":"Planting & soil","def":"The period after planting when the contractor waters, weeds, fertilizes and replaces plants.","mod":7},
  {"term":"Plant establishment period","abbr":"PEP","also":"establishment period","cat":"Planting & soil","def":"The required care period after planting, before the owner accepts the landscape. The specs set its length and work.","mod":7},
  {"term":"Plant Establishment Work","abbr":"PEW","cat":"Planting & soil","def":"Caltrans's bid item that pays for the plant establishment period.","ex":"Caltrans 11-428704 item 30: Plant Establishment Work, LS.","mod":15},
  {"term":"Plant factor","abbr":"PF","cat":"Planting & soil","def":"A number for a plant's water use, from WUCOLS, used in MWELO water budgets.","mod":5},
  {"term":"Plant group","abbr":"","cat":"Planting & soil","def":"Caltrans's letter code for how a plant is supplied: A (No. 1 container), B (No. 5), C (balled and burlapped), E (bulb), F (flats), H (cutting), I (pot), K (24-inch box), M (liner), O (acorn), P (plugs), S (seedling), U (No. 15), Z (palm).","ex":"From the plant group table in the special provisions for Caltrans 11-430674 and 11-431064.","mod":7},
  {"term":"Plant legend","abbr":"","also":"plant schedule; plant list","cat":"Plans & drawings","def":"The table of every plant with its symbol, name, size, spacing and quantity notes.","mod":7},
  {"term":"Plant palette","abbr":"","cat":"Planting & soil","def":"The set of plants a designer chose for a project.","mod":7},
  {"term":"Plant replacement","abbr":"","also":"replacement planting","cat":"Planting & soil","def":"Replacing dead or poor plants during establishment or warranty, at your cost. Carry an amount for it.","mod":7},
  {"term":"Plant substitution","abbr":"","cat":"Planting & soil","def":"Using a different plant or size than specified, which needs written approval first.","mod":8},
  {"term":"Planting details","abbr":"PLD","cat":"Plans & drawings","def":"Sheets of planting installation details, like tree planting and staking.","ex":"Caltrans 11-428704: PLD-1.","mod":4},
  {"term":"Planting pit","abbr":"","also":"plant hole","cat":"Planting & soil","def":"The hole dug for a plant. Details set its size, often a multiple of the root ball width.","ex":"Caltrans 11-428704 planting notes call for 48-inch diameter holes for Group K trees.","mod":7},
  {"term":"Planting plan","abbr":"PP","cat":"Plans & drawings","def":"The sheets showing where every plant goes. Caltrans uses PP sheet codes.","ex":"Caltrans 11-428704: PP-1 to PP-7.","mod":4},
  {"term":"Planting quantities","abbr":"PQ","cat":"Plans & drawings","def":"Caltrans sheet listing planting quantities by sheet.","ex":"Caltrans 11-428704: PQ-1.","mod":15},
  {"term":"Plants per square foot","abbr":"","cat":"Planting & soil","def":"How many plants fit in 1 SF at a given spacing. Multiply by the area to get the count.","mod":7},
  {"term":"Plug","abbr":"","also":"plug number","cat":"Bidding & contracts","def":"An amount a GC adds to cover something a sub left out or didn't quote. A sub can also carry a plug for an item it has no quote for.","mod":13},
  {"term":"Plug (plant)","abbr":"","also":"plug tray","cat":"Planting & soil","def":"A small plant grown in its own cell of a tray, often grasses or groundcovers. Caltrans calls this Plant Group P. (Bidding slang “plug” means something else.)","mod":7},
  {"term":"Plus or minus","abbr":"±","also":"approx","cat":"Units & measurement","def":"Means “about” on plans and quantities. Field-check anything marked ±.","mod":0},
  {"term":"Point of connection","abbr":"POC","cat":"Irrigation","def":"Where the irrigation system connects to its water supply, often at a meter or stub-out.","mod":4},
  {"term":"Polyvinyl chloride","abbr":"PVC","cat":"Irrigation","def":"The plastic most irrigation pipe is made of. Sold by schedule (wall thickness) or class (pressure rating).","mod":6},
  {"term":"Pop-up sprinkler","abbr":"","also":"pop-up spray; pop-up head","cat":"Irrigation","def":"A head that rises out of the ground when the zone runs and drops back flush when off. Sold by pop-up height: 4\", 6\", 12\".","ex":"Caltrans 11-428704 item 53: Pop-Up Sprinkler Assembly (Gear Driven), 1 EA.","mod":6},
  {"term":"Port of San Diego","abbr":"","cat":"Agencies & organizations","def":"The agency that runs San Diego Bay tidelands. It bids landscape and park work along the waterfront.","mod":3},
  {"term":"Portland cement concrete","abbr":"PCC","also":"concrete","cat":"Hardscape & site work","def":"Regular concrete made with cement, sand, rock and water.","mod":7},
  {"term":"Post mile","abbr":"PM","cat":"Plans & drawings","def":"Caltrans's way to mark locations along a highway, in miles from the county line.","ex":"Caltrans 11-428704 location: 11-SD-805-3.4/5.1 (District 11, San Diego County, Route 805, post miles 3.4 to 5.1).","mod":15},
  {"term":"Post-emergent herbicide","abbr":"","also":"post-emergent","cat":"Planting & soil","def":"A weed killer used on weeds that are already growing.","mod":7},
  {"term":"Potable water","abbr":"","also":"drinking water; domestic water","cat":"Irrigation","def":"Water safe for drinking. Irrigation from potable water needs a backflow preventer.","mod":6},
  {"term":"Pothole","abbr":"","also":"potholing","cat":"Grading, demo & erosion control","def":"Digging a small hole, often by vacuum truck, to find the exact depth and location of a buried utility.","mod":12},
  {"term":"Pound","abbr":"LB","also":"lb; #","cat":"Units & measurement","def":"A unit of weight. Fertilizer and some soil additives are paid by the pound.","ex":"Caltrans 11-428704 item 22: Iron Sulfate (LB), 230 LB.","mod":0},
  {"term":"Pounds per square inch","abbr":"PSI","also":"psi","cat":"Units & measurement","def":"The unit for water pressure. Pipe classes and sprinkler operating pressures are given in PSI.","mod":6},
  {"term":"Power of attorney","abbr":"POA","cat":"Licensing, insurance & bonds","def":"The surety's document showing who may sign bonds for it. Attach it to the bid bond.","mod":14},
  {"term":"Pre-bid meeting","abbr":"","also":"pre-bid conference; pre-bid","cat":"Bidding & contracts","def":"A meeting before bids are due where the owner explains the job and answers questions.","mod":12},
  {"term":"Pre-construction meeting","abbr":"","also":"precon meeting; kickoff","cat":"Bidding & contracts","def":"The meeting after award and before work starts, to go over schedule, submittals, safety, contacts and paperwork.","mod":16},
  {"term":"Pre-emergent herbicide","abbr":"","also":"pre-emergent","cat":"Planting & soil","def":"A weed killer that stops seeds from sprouting. Must be applied by licensed people on many jobs.","mod":7},
  {"term":"Pre-plant fertilizer","abbr":"","cat":"Planting & soil","def":"Fertilizer spread and mixed into the soil before planting, per the soils report.","mod":7},
  {"term":"Precipitation rate","abbr":"PR","cat":"Irrigation","def":"How fast a zone puts water on the ground, in inches per hour.","mod":6},
  {"term":"Precon","abbr":"","also":"preconstruction","cat":"Construction phrases & jargon","def":"The work before building starts: estimating, design input, scheduling and buyout. Larger GCs have precon departments.","mod":3},
  {"term":"Predetermined increase","abbr":"","cat":"Public works & compliance","def":"A raise already written into a wage determination, marked with asterisks. You must pay it when it takes effect, so price it in.","mod":11},
  {"term":"Preliminary notice","abbr":"","also":"20-day notice; prelim","cat":"Bidding & contracts","def":"A notice sent to the owner, GC and lender early in a job. It protects your lien, stop payment notice and payment bond rights. Send it within 20 days of first furnishing work.","mod":8},
  {"term":"Premium audit","abbr":"","also":"insurance audit","cat":"Licensing, insurance & bonds","def":"The insurer's year-end check of your actual payroll or sales to set your final premium.","mod":9},
  {"term":"Prequalification","abbr":"","also":"prequal","cat":"Bidding & contracts","def":"A form or process that approves you to bid before you bid. Some GCs and agencies require it.","mod":2},
  {"term":"Prescriptive specification","abbr":"","cat":"Specifications","def":"A spec that says exactly what product and method to use.","mod":5},
  {"term":"Pressure loss","abbr":"","also":"friction loss","cat":"Irrigation","def":"Pressure lost as water moves through pipe, fittings and valves. Designers size pipe to keep it low.","mod":6},
  {"term":"Pressure regulating valve","abbr":"PRV","also":"pressure regulator","cat":"Irrigation","def":"A valve that lowers water pressure to a set level.","ex":"Caltrans 11-428704 item 64: Pressure Regulating Valve, 1 EA.","mod":6},
  {"term":"Pressure vacuum breaker","abbr":"PVB","cat":"Irrigation","def":"A backflow assembly that must be installed above the highest head. Common on small systems where allowed.","mod":6},
  {"term":"Prevailing wage","abbr":"PW","cat":"Public works & compliance","def":"The minimum wage and benefits the state sets for each craft and county on public works. Required on public works over $1,000.","mod":1},
  {"term":"Price index","abbr":"","cat":"Money & estimating","def":"A published measure of price changes used in some contracts to adjust payment for items like asphalt or fuel.","mod":8},
  {"term":"Primary and non-contributory","abbr":"P&NC","cat":"Licensing, insurance & bonds","def":"Insurance wording meaning your policy pays first for claims from your work, without asking the GC's or owner's insurance to share.","mod":2},
  {"term":"Prime contract","abbr":"","cat":"Bidding & contracts","def":"The contract between the owner and the prime contractor.","mod":1},
  {"term":"Prime contractor","abbr":"","also":"prime; direct contractor","cat":"Bidding & contracts","def":"The contractor hired directly by the owner. On landscape-only public jobs, that can be you.","mod":1},
  {"term":"Principal","abbr":"","cat":"Licensing, insurance & bonds","def":"On a bond, the contractor whose work the bond guarantees: you.","mod":2},
  {"term":"Product data","abbr":"","also":"cut sheet; data sheet","cat":"Specifications","def":"The maker's printed sheet with a product's specs, sent as a submittal.","mod":5},
  {"term":"Production rate","abbr":"","also":"productivity rate","cat":"Money & estimating","def":"How fast work gets done: labor hours per unit, or units per crew day.","ex":"Example: one crew trenches and installs 400 LF of lateral per day. Use your own numbers.","mod":9},
  {"term":"Productivity loss","abbr":"","cat":"Money & estimating","def":"Paid hours that don't produce work, from weather, short work windows, waiting or rework.","mod":9},
  {"term":"Products-completed operations","abbr":"","also":"completed ops","cat":"Licensing, insurance & bonds","def":"Liability coverage for claims that come up after your work is finished. Contracts often require it for years after completion.","mod":2},
  {"term":"Profit","abbr":"","also":"fee","cat":"Money & estimating","def":"What's left after all job costs and overhead are paid.","mod":10},
  {"term":"Progress payment","abbr":"","also":"partial payment","cat":"Bidding & contracts","def":"Payment for work done so far, usually each month, less retention.","mod":16},
  {"term":"Project labor agreement","abbr":"PLA","cat":"Public works & compliance","def":"An agreement between an owner and unions for one project, setting labor terms. On PLA jobs you may have to hire through union halls and pay into union plans.","mod":3},
  {"term":"Project manual","abbr":"","also":"spec book","cat":"Specifications","def":"The book of bidding forms, contract terms and technical specs for a private or building project.","mod":5},
  {"term":"Prompt payment","abbr":"","cat":"Bidding & contracts","def":"California law says a contractor must pay its subs within 7 days after it receives a progress payment, unless they agreed otherwise in writing (Business and Professions Code 7108.5).","mod":16},
  {"term":"Property line","abbr":"PL","also":"P/L","cat":"Plans & drawings","def":"The legal edge of a property. Don't build or store outside it without permission. (PL can also mean a planting legend sheet, so read the context.)","mod":4},
  {"term":"Proposal","abbr":"","also":"quote; scope letter","cat":"Bidding & contracts","def":"A sub's written offer to a GC: scope, price and terms. Caltrans also calls its bid package the “proposal.”","mod":13},
  {"term":"Protect in place","abbr":"PIP","cat":"Plans & drawings","def":"Keep an existing item and don't damage it during work. Damage is fixed at your cost.","mod":4},
  {"term":"Provide","abbr":"","cat":"Specifications","def":"In specs, “provide” means furnish and install, complete and ready to use.","mod":5},
  {"term":"Prune existing plants","abbr":"","also":"pruning","cat":"Planting & soil","def":"Cutting back existing trees and shrubs as the specs say.","ex":"Caltrans 11-428804 item 31: Prune Existing Plants, LS.","mod":15},
  {"term": "Public Contract Code", "abbr": "PCC", "cat": "Public works & compliance", "def": "The California code that governs how public agencies bid and award construction contracts, including subcontractor listing (sections 4100 to 4114), bid mistakes (5100 to 5110) and retention (7201).", "mod": 14},
  {"term":"Public works","abbr":"","also":"public work","cat":"Public works & compliance","def":"In California, construction, alteration, demolition, installation, repair or maintenance paid for in whole or part with public funds (Labor Code 1720). Prevailing wage applies.","mod":1},
  {"term":"Pull box","abbr":"","also":"splice box","cat":"Irrigation","def":"A buried box where wires are pulled through and spliced.","mod":6},
  {"term":"Punch list","abbr":"","also":"punchlist","cat":"Bidding & contracts","def":"The list of fixes found at the final walk-through. All items must be done before final acceptance.","mod":1},
  {"term":"Punch out","abbr":"","cat":"Construction phrases & jargon","def":"Finishing every item on the punch list.","mod":16},
  {"term":"Purple pipe","abbr":"","also":"recycled water pipe","cat":"Irrigation","def":"Pipe colored purple to mark recycled water. Heads, valve boxes and tags are marked too.","mod":6},
  {"term":"PWC-100","abbr":"","cat":"Public works & compliance","def":"The DIR form an awarding body files to report a public works contract award, listing the prime and subs.","mod":11},
  {"term":"Qualified SWPPP Developer","abbr":"QSD","cat":"Public works & compliance","def":"A certified person who writes and updates a SWPPP under the Construction General Permit.","mod":7},
  {"term":"Qualified SWPPP Practitioner","abbr":"QSP","cat":"Public works & compliance","def":"A certified person who carries out a SWPPP on site: inspections, BMP checks and sampling.","mod":7},
  {"term":"Qualifier","abbr":"","also":"qualifying individual","cat":"Licensing, insurance & bonds","def":"The person whose experience and exam qualify a company's license.","mod":2},
  {"term":"Quality assurance","abbr":"QA","cat":"Specifications","def":"The owner's checks and testing that your QC is working.","mod":5},
  {"term":"Quality control","abbr":"QC","cat":"Specifications","def":"Your own checks that the work meets the specs.","mod":5},
  {"term":"Quantity","abbr":"QTY","cat":"Units & measurement","def":"How many units. On a bid form, the owner's estimated quantity for each item.","mod":0},
  {"term":"Quantity table","abbr":"","also":"quantity sheet","cat":"Plans & drawings","def":"A Caltrans sheet listing quantities for each bid item by plan sheet. Check them against your own takeoff.","ex":"Caltrans 11-428704 sheet PQ-1 lists planting quantities; IQ-1 and IQ-2 list irrigation quantities.","mod":15},
  {"term":"Quick coupler valve","abbr":"QCV","also":"quick coupler; QC","cat":"Irrigation","def":"A valve on the mainline where a key and hose plug in for hand watering.","mod":6},
  {"term":"Quote expiration","abbr":"","also":"valid until","cat":"Money & estimating","def":"The last date a quoted price is good. Bid jobs can award months later, so ask for prices held long enough.","mod":8},
  {"term":"Radius","abbr":"","also":"throw","cat":"Irrigation","def":"How far a sprinkler throws water, in feet.","mod":6},
  {"term":"Rain Event Action Plan","abbr":"REAP","cat":"Public works & compliance","def":"A short plan made before forecast rain listing the storm water steps you'll take.","ex":"Caltrans 11-428704 item 11: Rain Event Action Plan, 4 EA.","mod":7},
  {"term":"Rain sensor","abbr":"","also":"rain shutoff","cat":"Irrigation","def":"A device that stops irrigation when it rains.","mod":6},
  {"term":"Rebar","abbr":"","also":"reinforcing steel","cat":"Hardscape & site work","def":"Steel bars set in concrete for strength, sized by number in eighths of an inch (#4 = 1/2 inch).","mod":7},
  {"term":"Rebid","abbr":"","cat":"Bidding & contracts","def":"When an agency throws out all bids and advertises the job again, often after changing it.","mod":14},
  {"term":"Recycled water","abbr":"","also":"reclaimed water; purple pipe water","cat":"Irrigation","def":"Treated wastewater used for irrigation. It has its own pipe color (purple), signs, separation and inspection rules.","ex":"Caltrans 11-428704 converted I-805 irrigation in Chula Vista from potable to recycled water.","mod":12},
  {"term":"Recycled water connection assembly","abbr":"RWCA","cat":"Irrigation","def":"Caltrans term for the assembly that connects an irrigation system to a recycled water supply.","ex":"Caltrans 11-428804 item 71: 3\" Recycled Water Connection Assembly, 6 EA.","mod":15},
  {"term":"Recycled water identification and warning signs","abbr":"RWWS","cat":"Irrigation","def":"Signs required where recycled water is used, telling people not to drink it.","ex":"Caltrans 11-428704 item 49: Recycled Water Identification and Warning Signs, LS.","mod":15},
  {"term":"Reduced pressure principle assembly","abbr":"RP","also":"RPPA; RPZ; reduced pressure backflow","cat":"Irrigation","def":"The highest-protection backflow assembly. Often required by water agencies for commercial irrigation. Must be above ground.","mod":6},
  {"term":"Reference","abbr":"REF","cat":"Plans & drawings","def":"Marks information shown for reference only, like a dimension from another sheet.","mod":4},
  {"term":"Reference standard","abbr":"","cat":"Specifications","def":"An outside standard a spec points to, like an ASTM or AWWA standard. It counts as part of the spec.","mod":5},
  {"term":"Regional Water Quality Control Board","abbr":"RWQCB","also":"regional board","cat":"Agencies & organizations","def":"One of nine regional water boards. The San Diego Regional Board enforces storm water rules locally.","mod":7},
  {"term":"Reject all bids","abbr":"","cat":"Bidding & contracts","def":"Public agencies usually keep the right to throw out every bid, for example when all prices are over budget.","mod":14},
  {"term":"Relative compaction","abbr":"RC","also":"percent compaction","cat":"Grading, demo & erosion control","def":"How tight soil is packed, as a percent of its maximum dry density. Specs often call for 90% or more under paving and less in planting areas, where over-compacted soil is bad for plants.","mod":7},
  {"term":"Remote control valve","abbr":"RCV","also":"zone valve; solenoid valve","cat":"Irrigation","def":"An electric valve that opens and closes one zone when the controller signals it.","ex":"Caltrans 11-428704 item 37: 1 1/2\" Remote Control Valve, 4 EA.","mod":6},
  {"term":"Remove and replace","abbr":"R&R","cat":"Plans & drawings","def":"Take something out and put it back, or put in a new one, as the plans say.","mod":4},
  {"term":"Remove irrigation facility","abbr":"","cat":"Irrigation","def":"Caltrans work to take out existing irrigation parts that won't be used.","ex":"Caltrans 11-428704 item 34: Remove Irrigation Facility, LS.","mod":15},
  {"term":"Rental rate","abbr":"","cat":"Money & estimating","def":"What a rental yard charges for equipment by the day, week or month, plus delivery and fuel.","mod":9},
  {"term":"Request for information","abbr":"RFI","cat":"Bidding & contracts","def":"A written question about the documents. During bidding, answers usually come as addenda; after award, as RFI responses.","mod":12},
  {"term":"Request for proposal","abbr":"RFP","cat":"Bidding & contracts","def":"A request for firms to send proposals. The owner may choose on price plus other things, like experience and approach.","mod":3},
  {"term":"Request for qualifications","abbr":"RFQ","also":"statement of qualifications; SOQ","cat":"Bidding & contracts","def":"A request for firms to show their experience, often to make a short list before pricing. Some people use RFQ to mean “request for quote,” so read the context.","mod":3},
  {"term":"Resident engineer","abbr":"RE","also":"the Engineer","cat":"Bidding & contracts","def":"The agency's engineer in charge of a contract in the field. Caltrans specs call this person “the Engineer.”","mod":16},
  {"term":"Responsible","abbr":"","also":"responsible bidder","cat":"Bidding & contracts","def":"A bidder able to do the work: properly licensed, registered and qualified.","mod":1},
  {"term":"Responsible managing employee","abbr":"RME","cat":"Licensing, insurance & bonds","def":"A license qualifier who is an employee, working at least 32 hours a week or 80% of the company's operating hours.","mod":2},
  {"term":"Responsible managing officer","abbr":"RMO","cat":"Licensing, insurance & bonds","def":"A license qualifier who is an owner or officer of the company.","mod":2},
  {"term":"Responsive","abbr":"","also":"responsive bid","cat":"Bidding & contracts","def":"A bid that followed all the bid instructions and included every required form.","mod":1},
  {"term":"Retaining wall","abbr":"RW","cat":"Hardscape & site work","def":"A wall that holds back soil. Taller walls need engineering and permits, and may need a different license.","mod":7},
  {"term":"Retention","abbr":"","also":"retainage","cat":"Bidding & contracts","def":"Money held back from each payment until the work is complete. California limits it to 5% on most public jobs (Public Contract Code 7201) and on most private contracts signed on or after January 1, 2026 (Civil Code 8811), with some exceptions.","mod":16},
  {"term":"Revised Standard Plans","abbr":"RSP","cat":"Plans & drawings","def":"Updated Caltrans standard details, bound into the job's plan set.","ex":"Caltrans 11-428704 sheets 59 to 65 are Revised Standard Plans.","mod":15},
  {"term":"Revised Standard Specifications","abbr":"RSS","cat":"Specifications","def":"Caltrans's statewide updates to its Standard Specifications, bound into each job's special provisions.","mod":5},
  {"term":"Revision","abbr":"REV","cat":"Plans & drawings","def":"A change to a sheet after it was first issued, noted in the revision block with a date.","mod":4},
  {"term":"Revision cloud","abbr":"","also":"cloud; delta","cat":"Plans & drawings","def":"A wavy outline and a numbered triangle marking what an addendum or revision changed.","mod":4},
  {"term":"Right of way","abbr":"R/W","also":"ROW","cat":"Plans & drawings","def":"The land owned or controlled by the agency for a road or utility. Work and storage usually must stay inside it.","mod":4},
  {"term":"Ripping","abbr":"","also":"rip","cat":"Grading, demo & erosion control","def":"Breaking up hard soil with a shank on a machine, deeper than a tiller can reach.","mod":7},
  {"term":"Riprap","abbr":"","also":"rock slope protection","cat":"Hardscape & site work","def":"Large rock placed to protect slopes and channels from erosion.","mod":7},
  {"term":"Riser","abbr":"","cat":"Irrigation","def":"A short vertical pipe that lifts a sprinkler above the ground or plants.","ex":"Caltrans 11-431064 item 51: Riser Sprinkler Assembly, 120 EA.","mod":6},
  {"term":"Risk level","abbr":"","cat":"Public works & compliance","def":"Under the Construction General Permit, a site's level (1, 2 or 3) based on its erosion risk and the water it drains to. Higher levels mean more inspections and sampling.","mod":7},
  {"term":"Roadside clearing","abbr":"","cat":"Planting & soil","def":"Caltrans item for removing weeds, trash and unwanted plants from roadside areas.","ex":"Caltrans 11-428704 item 20: Roadside Clearing, LS.","mod":15},
  {"term":"Roadside sign","abbr":"","cat":"Hardscape & site work","def":"A sign on posts along a highway.","ex":"Caltrans 11-428804 item 92: Roadside Sign - One Post, 2 EA.","mod":15},
  {"term":"Roadway excavation","abbr":"","cat":"Grading, demo & erosion control","def":"Caltrans's item for digging soil along a highway, paid by the CY.","ex":"Caltrans 11-430674 item 26: Roadway Excavation, 6,480 CY.","mod":15},
  {"term":"Rock blanket","abbr":"","also":"cobble blanket","cat":"Planting & soil","def":"A layer of larger rock or cobble over an area, often on slopes or in drainage areas.","ex":"Caltrans 11-430674 item 30: Rock Blanket, 13,300 SQFT.","mod":7},
  {"term":"Rock mulch","abbr":"","also":"gravel mulch","cat":"Planting & soil","def":"Crushed rock or gravel used as mulch, priced by SF or by the ton.","ex":"Caltrans 11-431064 item 32: Gravel Mulch (Type 1), 115,000 SQFT.","mod":7},
  {"term":"Rolled erosion control product","abbr":"RECP","cat":"Grading, demo & erosion control","def":"The general name for erosion blankets and mats.","ex":"Caltrans 11-428804 item 79: Rolled Erosion Control Product (Jute Mesh), 45,500 SQFT.","mod":7},
  {"term":"Root ball","abbr":"","cat":"Planting & soil","def":"The mass of roots and soil that comes with a plant.","mod":7},
  {"term":"Root barrier","abbr":"","cat":"Planting & soil","def":"A panel along paving or around a root ball that guides roots down and away from hardscape.","mod":7},
  {"term":"Root flare","abbr":"","also":"trunk flare","cat":"Planting & soil","def":"Where the trunk widens into the roots. Plant so it sits at or slightly above finished grade.","mod":7},
  {"term":"Root-bound","abbr":"","also":"pot-bound","cat":"Planting & soil","def":"A plant with roots circling the container. Specs often allow rejecting root-bound stock.","mod":7},
  {"term":"Rotary nozzle","abbr":"","also":"multi-stream rotary nozzle","cat":"Irrigation","def":"A spray-head nozzle that throws many rotating streams at a low precipitation rate, good for slopes and clay soils.","mod":6},
  {"term":"Rototill","abbr":"","also":"till","cat":"Planting & soil","def":"Mixing soil and amendments with a tiller to a set depth.","mod":7},
  {"term":"Rough grading","abbr":"","also":"rough grade; mass grading","cat":"Grading, demo & erosion control","def":"Moving soil to close to the final grades, within the tolerance the specs allow. Often by the civil contractor before landscape starts.","mod":7},
  {"term":"Rough order of magnitude","abbr":"ROM","cat":"Money & estimating","def":"A very rough early price range, for budgeting only.","mod":13},
  {"term":"Safety data sheet","abbr":"SDS","cat":"Public works & compliance","def":"A product's safety sheet showing hazards, handling and first aid. Keep one for every chemical on site, like fertilizer, herbicide and PVC glue.","mod":9},
  {"term":"Sales tax","abbr":"","cat":"Money & estimating","def":"State and local tax on goods. On most construction, the contractor is the consumer of materials it installs and pays tax on them; plants and trees follow fixture rules. The statewide base rate is 7.25%, plus local district taxes.","mod":8},
  {"term":"Salinity","abbr":"EC","also":"electrical conductivity; ECe","cat":"Planting & soil","def":"The salt level in soil or water, measured as electrical conductivity. High salt hurts plants, and recycled water can add salt.","mod":7},
  {"term":"Salvage irrigation facility","abbr":"","cat":"Irrigation","def":"Caltrans work to remove existing parts carefully and deliver them to the agency.","ex":"Caltrans 11-428704 item 35: Salvage Irrigation Facility, LS.","mod":15},
  {"term":"Sample","abbr":"","cat":"Specifications","def":"A physical piece of a material, like mulch, DG or boulders, sent for approval before ordering.","mod":5},
  {"term":"San Diego Association of Governments","abbr":"SANDAG","cat":"Agencies & organizations","def":"The regional planning and transportation agency. It funds and builds transit and highway projects with Caltrans, which may include landscape work.","mod":3},
  {"term":"San Diego County Water Authority","abbr":"SDCWA","also":"Water Authority","cat":"Agencies & organizations","def":"The regional water wholesaler that supplies water to local districts in San Diego County.","mod":3},
  {"term":"San Diego Gas & Electric","abbr":"SDG&E","cat":"Agencies & organizations","def":"The local electric and gas utility. New power for an irrigation controller often needs an SDG&E service.","mod":12},
  {"term":"Sand bedding","abbr":"","also":"pipe bedding","cat":"Grading, demo & erosion control","def":"Sand placed under and around pipe in a trench to protect it.","ex":"Caltrans 11-428804 item 29: Sand Bedding, 840 CY.","mod":6},
  {"term":"Sawcut","abbr":"","also":"saw cut","cat":"Grading, demo & erosion control","def":"Cutting concrete or asphalt in a straight line with a saw before removing it, so the edge stays clean. Priced per LF by depth.","mod":7},
  {"term":"SBA Surety Bond Guarantee","abbr":"SBG","cat":"Licensing, insurance & bonds","def":"A U.S. Small Business Administration program that backs bonds for small contractors who can't get bonded on their own.","mod":2},
  {"term":"Scale","abbr":"","cat":"Plans & drawings","def":"How real distance relates to drawing distance, like 1\" = 20' meaning 1 inch on the sheet equals 20 feet.","mod":4},
  {"term":"Scarify","abbr":"","cat":"Grading, demo & erosion control","def":"Loosening the surface of soil, often before placing new soil or seeding.","mod":7},
  {"term":"Schedule","abbr":"SCHED","also":"table","cat":"Plans & drawings","def":"A table on the plans listing items and their details, like a sprinkler schedule or plant schedule.","mod":4},
  {"term":"Schedule 40 PVC","abbr":"SCH 40","also":"Sch 40","cat":"Irrigation","def":"PVC pipe with a set wall thickness for each size. Pressure rating drops as size goes up. Common for mainline in small sizes and for sleeves.","ex":"Caltrans 11-428704 item 57: 1\" Plastic Pipe (Schedule 40) (Supply Line), 1,390 LF.","mod":6},
  {"term":"Schedule 80 PVC","abbr":"SCH 80","also":"Sch 80","cat":"Irrigation","def":"Thicker-wall PVC pipe than Schedule 40, gray in color. Used for risers and nipples that need strength.","mod":6},
  {"term":"Schedule of values","abbr":"SOV","cat":"Bidding & contracts","def":"Your contract price split into lines for billing. Each pay application shows the percent complete on each line.","mod":16},
  {"term":"Scope gap","abbr":"","also":"gap; hole in the scope","cat":"Bidding & contracts","def":"Work that falls between two trades so nobody priced it. GCs hunt for gaps when leveling.","ex":"Example: the landscape sub excludes sleeves, the concrete sub excludes sleeves, and nobody carries them.","mod":13},
  {"term":"Scope letter","abbr":"","also":"proposal; quote","cat":"Bidding & contracts","def":"A sub's written description of what its price includes and excludes.","mod":12},
  {"term":"Scope of work","abbr":"SOW","also":"scope","cat":"Bidding & contracts","def":"Exactly what work is included in a bid or contract.","mod":1},
  {"term":"Scope overlap","abbr":"","also":"double scope","cat":"Bidding & contracts","def":"When two trades both price the same work. The GC pays twice unless it catches it.","mod":13},
  {"term":"Scope sheet","abbr":"","also":"bid form; scope checklist","cat":"Bidding & contracts","def":"A GC's list of what each trade's price must include. Fill it out and send it with your proposal.","mod":13},
  {"term":"Seat wall","abbr":"","cat":"Hardscape & site work","def":"A low wall built for sitting, often in plazas and parks.","mod":7},
  {"term":"Section","abbr":"SECT","also":"cross section","cat":"Plans & drawings","def":"A drawing of something cut through, to show its layers, like a planting area or wall section.","mod":4},
  {"term":"Section 32 01 90","abbr":"","also":"Operation and Maintenance of Planting","cat":"Specifications","def":"MasterFormat section number often used for landscape maintenance and plant establishment.","mod":16},
  {"term":"Section 32 80 00","abbr":"","also":"Irrigation","cat":"Specifications","def":"MasterFormat section number for irrigation.","mod":5},
  {"term":"Section 32 84 00","abbr":"","also":"Planting Irrigation","cat":"Specifications","def":"MasterFormat section number for planting irrigation systems.","mod":5},
  {"term":"Section 32 90 00","abbr":"","also":"Planting","cat":"Specifications","def":"MasterFormat section number for planting.","mod":5},
  {"term":"Section 32 91 13","abbr":"","also":"Soil Preparation","cat":"Specifications","def":"MasterFormat section number for soil preparation and amendments.","mod":5},
  {"term":"Section 32 92 00","abbr":"","also":"Turf and Grasses","cat":"Specifications","def":"MasterFormat section number for lawns, seeding, sod and hydroseeding.","mod":5},
  {"term":"Section 32 93 00","abbr":"","also":"Plants","cat":"Specifications","def":"MasterFormat section number for trees, shrubs and groundcovers.","mod":5},
  {"term":"Seed mix","abbr":"","also":"seed","cat":"Planting & soil","def":"A blend of seeds for turf or erosion control, specified by species and pounds per acre.","mod":7},
  {"term":"Self-performance","abbr":"","also":"self-perform","cat":"Bidding & contracts","def":"The share of the work a prime must do with its own crews and equipment. Caltrans generally requires at least 30% of the original total bid (Standard Specifications 5-1.13). Other agencies set their own minimums.","ex":"City of San Diego K-24-1952 required the prime to self-perform at least 50% of the base bid.","mod":14},
  {"term":"Shall","abbr":"","cat":"Specifications","def":"In specs, “shall” means you must. Caltrans now writes most rules as direct commands instead.","mod":5},
  {"term":"Sharpen your pencil","abbr":"","cat":"Construction phrases & jargon","def":"Slang for “lower your price.” Usually a GC asking a sub to cut its number.","mod":10},
  {"term":"Sheet","abbr":"SHT","cat":"Plans & drawings","def":"One page of the plan set.","mod":4},
  {"term":"Sheet code","abbr":"","also":"sheet number","cat":"Plans & drawings","def":"The short name on each sheet, like L-1.0, IP-3 or PQ-1. Letters tell the discipline.","mod":4},
  {"term":"Sheet index","abbr":"","also":"drawing index","cat":"Plans & drawings","def":"The list of every sheet in the set, usually on the title sheet. Check that you have every sheet.","mod":4},
  {"term":"Shop drawing","abbr":"","cat":"Specifications","def":"A drawing you make showing how you'll build or install something, sent as a submittal.","mod":16},
  {"term":"Shrinkage","abbr":"","also":"shrink","cat":"Grading, demo & erosion control","def":"Soil takes up less space after compaction than it did in the ground. Add extra fill to make up for it.","mod":7},
  {"term":"Shrub","abbr":"","cat":"Planting & soil","def":"A woody plant smaller than a tree, usually with several stems.","mod":7},
  {"term":"Silt fence","abbr":"","cat":"Grading, demo & erosion control","def":"A fabric fence on stakes that catches sediment from runoff.","ex":"Caltrans 11-422004 item 11: Temporary Silt Fence, 1,840 LF.","mod":7},
  {"term":"Similar","abbr":"SIM","cat":"Plans & drawings","def":"Built the same way as another detail or area shown, with small differences.","mod":4},
  {"term":"Single job limit","abbr":"","also":"single limit","cat":"Licensing, insurance & bonds","def":"The largest one job your surety will bond.","mod":2},
  {"term":"Site furnishings","abbr":"","also":"site amenities","cat":"Hardscape & site work","def":"Benches, trash cans, bike racks, tables and similar items installed on site.","mod":7},
  {"term":"Sleeve","abbr":"","cat":"Irrigation","def":"A larger pipe placed under paving so pipe or wire can be pulled through later. Find out who installs sleeves before the paving goes in.","ex":"Caltrans 11-431064 item 62: PVC Pipe Conduit (Sleeve), 80 LF.","mod":6},
  {"term":"Slope paving","abbr":"","cat":"Hardscape & site work","def":"Concrete paving on slopes, often under bridges, to stop erosion where plants won't grow.","ex":"Caltrans 11-428804 item 84: Slope Paving (Stamped Concrete), 220 CY.","mod":15},
  {"term":"Slope ratio","abbr":"","also":"2:1; H:V","cat":"Units & measurement","def":"Slope written as horizontal to vertical. 2:1 means 2 feet over for every 1 foot up. Steeper slopes cost more to plant and maintain.","mod":0},
  {"term":"Slow-release fertilizer","abbr":"","cat":"Planting & soil","def":"Fertilizer that releases nutrients over months.","ex":"Caltrans 11-428704 item 24: Slow-Release Fertilizer, 420 LB.","mod":15},
  {"term":"Small Business","abbr":"SB","cat":"Public works & compliance","def":"A California state certification from the Department of General Services. Caltrans may give bidders a small business preference.","mod":14},
  {"term":"Small Business Enterprise","abbr":"SBE","cat":"Public works & compliance","def":"A general term many agencies use for a certified small business. Each agency defines it its own way.","mod":14},
  {"term":"Small Local Business Enterprise","abbr":"SLBE","cat":"Public works & compliance","def":"A City of San Diego certification for small local businesses. City jobs often set SLBE/ELBE subcontracting goals.","mod":2},
  {"term":"Small project exemption","abbr":"","cat":"Public works & compliance","def":"DIR rule: contractors on public works of $25,000 or less (construction) or $15,000 or less (maintenance) don't have to register with DIR or file eCPR for that job. Prevailing wage still applies.","mod":11},
  {"term":"Small tools","abbr":"","also":"consumables","cat":"Money & estimating","def":"Hand tools and supplies used up on the job, often priced as a percent of labor.","mod":9},
  {"term":"Smart controller","abbr":"","also":"weather-based controller; ET controller","cat":"Irrigation","def":"A controller that adjusts watering by weather or soil moisture. MWELO and many agencies require them.","mod":6},
  {"term":"SMARTS","abbr":"","cat":"Public works & compliance","def":"The State Water Board's online system for filing storm water permit documents, like the NOI, SWPPP and reports.","mod":7},
  {"term":"Sod","abbr":"","also":"turf rolls","cat":"Planting & soil","def":"Rolls of grown grass laid like carpet. Priced per SF.","mod":7},
  {"term":"Sodium adsorption ratio","abbr":"SAR","cat":"Planting & soil","def":"A soil test number for sodium. High SAR can seal clay soil so water won't soak in.","mod":7},
  {"term":"Soil amendment","abbr":"","also":"amendment","cat":"Planting & soil","def":"Material mixed into soil to improve it, like compost, gypsum or sulfur, at a rate per area.","mod":7},
  {"term":"Soil preparation","abbr":"","also":"soil prep","cat":"Planting & soil","def":"Getting soil ready to plant: ripping, amending, fertilizing, mixing and fine grading.","mod":7},
  {"term":"Soil sample","abbr":"","cat":"Planting & soil","def":"Soil collected from the site and sent to a lab for testing.","mod":7},
  {"term":"Soil sulfur","abbr":"","cat":"Planting & soil","def":"A soil amendment that lowers pH in alkaline soil.","mod":7},
  {"term":"Soils report","abbr":"","also":"agronomic soils report","cat":"Planting & soil","def":"A lab report on soil samples that sets amendment and fertilizer rates.","mod":7},
  {"term":"Sole source","abbr":"","also":"no substitutions","cat":"Specifications","def":"Only one named product, or one supplier, is allowed. No “or equal.”","mod":5},
  {"term":"Solvent weld","abbr":"","also":"glue joint; primer and cement","cat":"Irrigation","def":"Joining PVC pipe and fittings with primer and solvent cement.","mod":6},
  {"term":"Special Provisions","abbr":"SP","cat":"Specifications","def":"Rules for one job only, written as changes and additions to the Standard Specifications. They govern over the standard specs.","mod":5},
  {"term":"Specimen","abbr":"","also":"specimen tree","cat":"Planting & soil","def":"An extra-nice, often larger plant chosen for a key spot. Costs more and may need tagging at the nursery.","mod":7},
  {"term":"Spoils","abbr":"","cat":"Grading, demo & erosion control","def":"Soil dug out of trenches and holes. Specs say whether you can reuse it or must haul it off.","mod":6},
  {"term":"Spot elevation","abbr":"SE","also":"spot grade","cat":"Plans & drawings","def":"A single elevation number written at a point on a grading plan.","mod":4},
  {"term":"Spray head","abbr":"","also":"spray; fixed spray","cat":"Irrigation","def":"A sprinkler with a fan-shaped spray, for small areas, typically under about 15 feet.","mod":6},
  {"term":"Spray-to-drip conversion","abbr":"","also":"retrofit","cat":"Irrigation","def":"Replacing spray heads with drip in an existing zone to save water.","mod":6},
  {"term":"Spread","abbr":"","also":"bid spread","cat":"Construction phrases & jargon","def":"The gap between bids, usually between the low bid and the second bid, or low and high.","ex":"Caltrans 11-428704: the five responsive bids ran from $1,176,120.00 to $3,311,895.00.","mod":15},
  {"term":"Sprinkler schedule","abbr":"","also":"irrigation legend","cat":"Plans & drawings","def":"The table of every irrigation symbol with maker, model, nozzle, pressure, radius and flow.","mod":6},
  {"term":"Square foot","abbr":"SF","also":"SQFT; sq ft; ft²","cat":"Units & measurement","def":"A unit of area 1 foot by 1 foot. Mulch, rock and hydroseed areas are often paid by the square foot.","ex":"Caltrans 11-422004 item 43: Hydroseed, 154,000 SQFT.","mod":0},
  {"term":"Square spacing","abbr":"","also":"grid spacing","cat":"Planting & soil","def":"Plants in a grid. Plants per SF = 1 ÷ (spacing in feet)².","mod":7},
  {"term":"Square yard","abbr":"SY","also":"SQYD; sq yd; yd²","cat":"Units & measurement","def":"A unit of area 3 feet by 3 feet (9 square feet).","ex":"Caltrans 11-428704 item 21: Weed Germination, 7,020 SQYD.","mod":0},
  {"term":"Stabilized construction entrance","abbr":"","also":"temporary construction entrance; rumble rack","cat":"Grading, demo & erosion control","def":"A rock pad or plate where trucks leave the site, to shake mud off tires.","ex":"Caltrans 11-428704 item 16: Temporary Construction Entrance, 8 EA.","mod":7},
  {"term":"Stabilized decomposed granite","abbr":"","also":"stabilized DG","cat":"Hardscape & site work","def":"DG mixed with a binder so it holds together and resists erosion.","ex":"City of San Diego K-24-1952 special provisions add a section for stabilized decomposed granite paving.","mod":7},
  {"term":"Stamped concrete","abbr":"","cat":"Hardscape & site work","def":"Concrete pressed with patterns and colored to look like stone or brick.","ex":"Caltrans 11-428804 item 85: Minor Concrete (Stamped Concrete), 6,670 SQFT.","mod":7},
  {"term":"Standard (detail or spec)","abbr":"STD","cat":"Plans & drawings","def":"A standard detail or spec, from an agency book such as Caltrans Standard Plans or San Diego Regional Standard Drawings.","mod":4},
  {"term":"Standard (tree form)","abbr":"STD","also":"single trunk","cat":"Planting & soil","def":"A tree with one main trunk. On plant lists, STD is the opposite of multi-trunk.","mod":7},
  {"term":"Standard Plans","abbr":"Std Plans","cat":"Plans & drawings","def":"An agency's book of standard details, used on every job without being redrawn.","ex":"Caltrans 11-428704 title sheet: “Standard Plans dated 2018.”","mod":4},
  {"term":"Standard Special Provisions","abbr":"SSP","cat":"Specifications","def":"Caltrans's ready-made paragraphs that designers drop into a job's special provisions.","mod":5},
  {"term":"Standard Specifications","abbr":"Std Specs","also":"SS","cat":"Specifications","def":"An agency's base spec book used on every job. Caltrans now updates its book often, and each job names the edition it uses.","ex":"Caltrans 11-428704 used the 2018 Standard Specifications.","mod":5},
  {"term":"State Water Resources Control Board","abbr":"SWRCB","also":"State Water Board","cat":"Agencies & organizations","def":"The state agency that issues the Construction General Permit for storm water.","mod":7},
  {"term":"Static pressure","abbr":"","cat":"Irrigation","def":"Water pressure when no water is flowing. Check it at the POC on the job walk.","mod":6},
  {"term":"Station (controller)","abbr":"","also":"zone","cat":"Irrigation","def":"One output on a controller that runs one valve or zone. Controllers are sold by station count.","mod":6},
  {"term":"Station (survey)","abbr":"Sta","cat":"Plans & drawings","def":"Distance in feet along a survey line, written like 262+48 (26,248 feet).","mod":4},
  {"term":"Stolons","abbr":"","also":"sprigs","cat":"Planting & soil","def":"Pieces of grass runners spread and rolled in to grow a lawn.","mod":7},
  {"term":"Stop payment notice","abbr":"","also":"stop notice","cat":"Bidding & contracts","def":"A notice that makes the owner, agency or lender hold money for an unpaid claimant. The main payment remedy on public jobs, where liens aren't allowed.","mod":16},
  {"term":"Stored materials","abbr":"","also":"materials on hand","cat":"Bidding & contracts","def":"Materials delivered and stored but not yet installed. Some contracts pay for them on your pay application if you document them.","mod":16},
  {"term":"Storm water annual report","abbr":"","cat":"Public works & compliance","def":"A yearly report on a project's storm water compliance, filed under the permit.","ex":"Caltrans 11-428704 item 13: Storm Water Annual Report, 2 EA.","mod":7},
  {"term":"Storm Water Pollution Prevention Plan","abbr":"SWPPP","cat":"Public works & compliance","def":"The written plan required under the Construction General Permit, showing how you'll keep sediment and pollutants out of storm drains.","ex":"Caltrans 11-428704 item 10: Prepare Storm Water Pollution Prevention Plan, LS.","mod":7},
  {"term":"Storm water sampling","abbr":"","cat":"Public works & compliance","def":"Collecting and testing runoff from the site during rain, when the permit requires it.","ex":"Caltrans 11-428704 item 12: Storm Water Sampling and Analysis Day, 4 EA.","mod":7},
  {"term":"Strainer","abbr":"","also":"wye strainer; Y-strainer","cat":"Irrigation","def":"A screen in the line that catches debris before valves or a backflow.","mod":6},
  {"term":"Street sweeping","abbr":"","cat":"Grading, demo & erosion control","def":"Sweeping streets near the site to remove tracked dirt, often required daily.","ex":"Caltrans 11-428704 item 17: Street Sweeping, LS.","mod":7},
  {"term":"Sub-subcontractor","abbr":"","also":"sub-sub; lower-tier sub","cat":"Bidding & contracts","def":"A company hired by a subcontractor.","mod":1},
  {"term":"Subcontract","abbr":"","also":"sub agreement","cat":"Bidding & contracts","def":"Your contract with the GC: scope, price, schedule, payment and risk terms.","mod":16},
  {"term":"Subcontractor","abbr":"sub","also":"trade contractor","cat":"Bidding & contracts","def":"A specialty company hired by the GC for one part of the work.","mod":1},
  {"term":"Subcontractor bond","abbr":"","also":"sub bond","cat":"Licensing, insurance & bonds","def":"A performance and payment bond a GC requires from a sub. The cost is usually added to the sub's price.","mod":2},
  {"term":"Subcontractor listing","abbr":"","also":"list of subcontractors; designation of subcontractors","cat":"Public works & compliance","def":"On California public works, the prime must list each sub whose work is more than one-half of 1% of the prime's bid (on streets and highways, more than that or $10,000, whichever is greater), with license and DIR numbers (Public Contract Code 4104).","mod":14},
  {"term":"Subcontractor quote","abbr":"","also":"sub quote","cat":"Money & estimating","def":"A sub's price for part of your work, like electrical service or boring.","mod":13},
  {"term":"Subcontractor substitution","abbr":"","cat":"Public works & compliance","def":"Replacing a listed sub on a public job. Only allowed with the agency's consent and for reasons the law lists (Public Contract Code 4107).","mod":14},
  {"term":"Subgrade","abbr":"","cat":"Grading, demo & erosion control","def":"The prepared soil under base rock and paving.","mod":7},
  {"term":"Submittal","abbr":"","cat":"Specifications","def":"Product data, samples, test reports or drawings sent for approval before you buy or install.","mod":5},
  {"term":"Substantial completion","abbr":"","cat":"Bidding & contracts","def":"When the work is done enough for the owner to use it for its purpose, even if small punch items remain. Often starts warranty periods.","mod":16},
  {"term":"Substitution request","abbr":"","cat":"Specifications","def":"Your formal request to use a different product than the one specified, with data showing it's equal. Check the deadline; some are due before bid.","mod":5},
  {"term":"Subsurface locator","abbr":"","also":"utility locator","cat":"Grading, demo & erosion control","def":"A service that finds and marks private buried lines that 811 doesn't cover.","ex":"Caltrans 11-431064 item 65: Subsurface Locator, LS.","mod":15},
  {"term":"Succulent","abbr":"","cat":"Planting & soil","def":"A plant that stores water in thick leaves or stems, like aloes and iceplant. Common in low-water landscapes.","mod":7},
  {"term":"Supplementary conditions","abbr":"","also":"special conditions","cat":"Specifications","def":"Changes to the general conditions for one project.","mod":5},
  {"term":"Supplementary Special Provisions","abbr":"SSP","cat":"Specifications","def":"City of San Diego name for job-specific changes to the Greenbook and Whitebook.","ex":"City of San Diego K-24-1952 Attachment E: Supplementary Special Provisions.","mod":5},
  {"term":"Surety","abbr":"","also":"surety company; bonding company","cat":"Licensing, insurance & bonds","def":"The company that issues bonds and guarantees your promise to the owner.","mod":2},
  {"term":"Survey control","abbr":"","also":"control points","cat":"Plans & drawings","def":"Known points the surveyor uses to lay out the job.","ex":"Caltrans 11-428704 sheet PC-1: project control.","mod":4},
  {"term":"Swale","abbr":"","cat":"Hardscape & site work","def":"A shallow channel in the ground that carries surface water.","mod":4},
  {"term":"Swell","abbr":"","also":"bulking","cat":"Grading, demo & erosion control","def":"Soil takes up more space after you dig it than it did in the ground. Trucks haul swelled (loose) yards.","mod":7},
  {"term":"Swing joint","abbr":"","also":"swing pipe","cat":"Irrigation","def":"Flexible or jointed fittings between the lateral and a head, so the head can be set to grade and can move without breaking.","mod":6},
  {"term":"Synthetic turf","abbr":"","also":"artificial turf","cat":"Hardscape & site work","def":"Plastic grass laid on prepared base. Installing it is synthetic products work.","mod":7},
  {"term":"T&M ticket","abbr":"","also":"extra work ticket; daily extra work report","cat":"Bidding & contracts","def":"A daily record of time and materials for extra work, signed by the GC or owner's rep that same day.","mod":16},
  {"term":"Tackifier","abbr":"","also":"binder","cat":"Grading, demo & erosion control","def":"A glue-like product added to hydroseed or mulch to keep it in place.","mod":7},
  {"term":"Tagging","abbr":"","also":"tag trees","cat":"Planting & soil","def":"Picking and marking specific trees at the nursery, sometimes with the landscape architect, for your job.","mod":8},
  {"term":"Takeoff","abbr":"","also":"quantity takeoff","cat":"Money & estimating","def":"Counting and measuring everything on the plans, with units, before any pricing.","mod":6},
  {"term":"Temporary protection fence","abbr":"TPF","also":"ESA fence","cat":"Grading, demo & erosion control","def":"A fence marking areas you must not enter, like trees or sensitive habitat.","ex":"Caltrans 11-428704 item 19: Temporary Protection Fence (Rope), 1,120 LF.","mod":15},
  {"term":"Temporary railing (Type K)","abbr":"K-rail","also":"Type K","cat":"Construction phrases & jargon","def":"Portable concrete barrier that protects a work area next to traffic. Paid per LF.","ex":"Caltrans 11-428704 item 7: Temporary Railing (Type K), 1,700 LF.","mod":15},
  {"term":"Tender","abbr":"","also":"tradesman","cat":"Public works & compliance","def":"Lower-paid helper classifications in some crafts, allowed only in set ratios to journeymen.","mod":11},
  {"term":"Termination for convenience","abbr":"","also":"T for C","cat":"Bidding & contracts","def":"A clause letting the owner end the contract even when you did nothing wrong. You're usually paid for work done and some costs of stopping. Profit on the unfinished work usually isn't paid.","mod":16},
  {"term":"Termination for default","abbr":"","also":"termination for cause","cat":"Bidding & contracts","def":"Ending a contract because the contractor failed to perform. The surety may be called to finish the work.","mod":16},
  {"term":"Three-part format","abbr":"","also":"Part 1, 2, 3","cat":"Specifications","def":"The standard layout of a spec section: Part 1 General, Part 2 Products, Part 3 Execution.","mod":5},
  {"term":"Thrust block","abbr":"","cat":"Irrigation","def":"Concrete poured against fittings on gasketed pipe to resist water pressure.","mod":6},
  {"term":"Tight bid","abbr":"","also":"tight number","cat":"Construction phrases & jargon","def":"A bid with little profit and little room for mistakes. Also used when all the bids came in close together.","mod":10},
  {"term":"Time and materials","abbr":"T&M","cat":"Bidding & contracts","def":"Getting paid for actual labor hours, materials and equipment plus a set markup, instead of a fixed price.","mod":16},
  {"term":"Time extension","abbr":"","also":"extension of time","cat":"Bidding & contracts","def":"Extra contract time granted by change order for a delay you didn't cause.","mod":16},
  {"term":"Time-related overhead","abbr":"TRO","cat":"Money & estimating","def":"A Caltrans bid item that pays field and home-office overhead per working day.","ex":"Caltrans 11-428704 item 2: Time-Related Overhead, 120 WDAY.","mod":10},
  {"term":"Title block","abbr":"","cat":"Plans & drawings","def":"The border box on each sheet with the project, sheet title, number, signer, stamp and dates.","mod":4},
  {"term":"Ton","abbr":"TON","also":"tn","cat":"Units & measurement","def":"2,000 pounds. Rock, base and asphalt are often bought by the ton.","ex":"Caltrans 11-422004 item 46: Hot Mix Asphalt (Type A), 20 TON.","mod":0},
  {"term":"Toolbox talk","abbr":"","also":"tailgate meeting; safety meeting","cat":"Public works & compliance","def":"A short safety meeting on the job. Cal/OSHA requires them at least every 10 working days on construction sites.","mod":9},
  {"term":"Top of curb","abbr":"TC","also":"TOC","cat":"Plans & drawings","def":"The elevation at the top of a curb.","mod":4},
  {"term":"Top of wall","abbr":"TW","also":"TOW","cat":"Plans & drawings","def":"The elevation at the top of a wall.","mod":4},
  {"term":"Topsoil","abbr":"","cat":"Planting & soil","def":"The top layer of soil. Specs may call for saving it, or importing topsoil that meets a standard.","mod":7},
  {"term":"Total hourly rate","abbr":"","also":"total prevailing rate","cat":"Public works & compliance","def":"Basic hourly rate plus employer payments: the real minimum cost per hour before taxes and insurance.","mod":11},
  {"term":"Tracer wire","abbr":"","also":"locator wire","cat":"Irrigation","def":"A wire laid with plastic pipe so it can be found later with a locator.","mod":6},
  {"term":"Traffic control","abbr":"TC","also":"traffic handling","cat":"Construction phrases & jargon","def":"Signs, cones, arrow boards and flaggers that keep traffic safe around work. Usually a sub's scope on Caltrans jobs.","ex":"Caltrans 11-428704 item 4: Traffic Control System, LS.","mod":15},
  {"term":"Traffic control technician","abbr":"TCT","cat":"Construction phrases & jargon","def":"A trained worker required on Caltrans closures to set and watch traffic control.","mod":15},
  {"term":"Traffic handling plan","abbr":"TH","cat":"Plans & drawings","def":"Caltrans sheets showing lane closures, signs and devices for traffic during work.","ex":"Caltrans 11-428704: TH-1 to TH-4.","mod":15},
  {"term":"Training fund contribution","abbr":"","cat":"Public works & compliance","def":"The per-hour amount for apprenticeship training that is part of many prevailing wage rates, paid to a program or the California Apprenticeship Council.","mod":11},
  {"term":"Transformer","abbr":"","cat":"Hardscape & site work","def":"A device that changes line voltage to low voltage for landscape lights. Sized by total watts.","mod":7},
  {"term":"Treated wood waste","abbr":"TWW","cat":"Public works & compliance","def":"Old wood treated with preservatives, like guardrail posts, that must be handled and disposed of under special rules.","ex":"Caltrans 11-422004 item 15: Treated Wood Waste, 130 LB.","mod":15},
  {"term":"Tree protection zone","abbr":"TPZ","also":"root protection zone","cat":"Planting & soil","def":"An area around an existing tree fenced off during work to protect its roots.","mod":12},
  {"term":"Tree staking","abbr":"","also":"stakes","cat":"Planting & soil","def":"Wood stakes and ties that hold a young tree upright while it roots in. Details set the number and size.","mod":7},
  {"term":"Tree ties","abbr":"","also":"cinch ties","cat":"Planting & soil","def":"Flexible ties that fasten a tree to its stakes without cutting the bark.","mod":7},
  {"term":"Tree well sprinkler assembly","abbr":"","cat":"Irrigation","def":"Caltrans term for the bubbler or head assembly at a tree basin.","ex":"Caltrans 11-428704 item 51: Tree Well Sprinkler Assembly, 180 EA.","mod":15},
  {"term":"Trench","abbr":"","cat":"Grading, demo & erosion control","def":"A narrow ditch for pipe or wire. Specs set depth and backfill.","mod":6},
  {"term":"Trencher","abbr":"","cat":"Irrigation","def":"A machine that digs narrow trenches for pipe and wire. Rocky or root-filled soil slows it down.","mod":9},
  {"term":"Triangular spacing","abbr":"","also":"offset spacing","cat":"Planting & soil","def":"Rows offset by half a space. Plants per SF = 1.155 ÷ (spacing in feet)². Uses about 15% more plants than square spacing.","mod":7},
  {"term":"Turf","abbr":"","also":"lawn; grass","cat":"Planting & soil","def":"Grass areas, installed by sod, seed, stolons or hydroseed. Many new commercial landscapes limit turf under MWELO.","mod":7},
  {"term":"Turnkey","abbr":"","cat":"Construction phrases & jargon","def":"Finished and ready to use, with nothing left for the owner to do.","mod":1},
  {"term":"Turnover","abbr":"","cat":"Construction phrases & jargon","def":"Handing the finished work to the owner, with training, manuals and keys or controller codes.","mod":16},
  {"term":"Two-wire","abbr":"","also":"decoder system","cat":"Irrigation","def":"A control system using one two-wire cable to all valves, with a decoder at each valve.","mod":6},
  {"term":"Type 1 plant establishment","abbr":"","also":"Type 1 PEP","cat":"Planting & soil","def":"One of the plant establishment types in the Caltrans specifications. The special provisions say which type applies and how long it lasts.","ex":"Caltrans 11-428704: Type 1 plant establishment, 250 working days.","mod":15},
  {"term":"Typical","abbr":"TYP","cat":"Plans & drawings","def":"Applies to every similar place on the plans, as well as the one shown. One “TYP” note can mean dozens of items.","mod":4},
  {"term":"Umbrella policy","abbr":"","also":"umbrella; excess liability","cat":"Licensing, insurance & bonds","def":"Extra liability coverage on top of your general liability, auto and employer's liability limits.","mod":2},
  {"term":"Unbalanced bid","abbr":"","cat":"Money & estimating","def":"Item prices that don't match each item's real cost plus its share of overhead and profit. A badly unbalanced public bid can be rejected.","mod":10},
  {"term":"Unconditional waiver and release","abbr":"","also":"unconditional release","cat":"Bidding & contracts","def":"A lien release that takes effect when signed, paid or not. Only sign one after the money is in your account.","mod":16},
  {"term":"Underbilling","abbr":"","also":"costs in excess","cat":"Money & estimating","def":"When you've done more work than you've billed. It hurts cash flow.","mod":16},
  {"term":"Underdrain","abbr":"","also":"subdrain; perforated pipe","cat":"Hardscape & site work","def":"A pipe with holes laid in gravel to carry away water under the ground.","ex":"Caltrans 11-422004 item 51: 6\" Perforated Plastic Pipe Underdrain, 230 LF.","mod":7},
  {"term":"Underutilized Disadvantaged Business Enterprise","abbr":"UDBE","cat":"Public works & compliance","def":"A narrower DBE group Caltrans used for goals on some past federal-aid contracts. Read each job's special provisions for which goal applies.","mod":14},
  {"term":"Unit cost","abbr":"","cat":"Money & estimating","def":"Your cost for one unit of work before markup, like cost per LF of pipe.","mod":9},
  {"term":"Unit of measure","abbr":"UOM","also":"unit","cat":"Units & measurement","def":"The unit an item is counted or paid in: EA, LF, SF, CY, LS and so on.","mod":0},
  {"term":"Unit price","abbr":"","cat":"Bidding & contracts","def":"The price for one unit of work: per tree, per valve, per foot. On unit price bids you're paid unit price times the measured quantity.","mod":3},
  {"term":"Unit price contract","abbr":"","also":"unit price bid","cat":"Bidding & contracts","def":"A contract where you price each item per unit and the owner gives the quantities. You're paid for what's actually installed, except final pay items.","mod":6},
  {"term":"Uplight","abbr":"","cat":"Hardscape & site work","def":"A light aimed up at a tree, wall or sign.","mod":7},
  {"term":"Use tax","abbr":"","cat":"Money & estimating","def":"Tax owed on goods bought without California sales tax, like out-of-state purchases, used here.","mod":8},
  {"term":"Utility plan","abbr":"U","cat":"Plans & drawings","def":"Sheets showing existing and new utilities. Check them for conflicts with your trenches.","mod":4},
  {"term":"Vacuum excavation","abbr":"","also":"vac truck; hydro-excavation","cat":"Grading, demo & erosion control","def":"Digging with water or air and a vacuum hose, used to pothole near utilities safely.","mod":12},
  {"term":"Value engineering","abbr":"VE","cat":"Bidding & contracts","def":"Finding a cheaper way to meet the same need, like a different product or layout. Owners ask for VE options when bids come in over budget.","mod":13},
  {"term":"Value Engineering Change Proposal","abbr":"VECP","cat":"Bidding & contracts","def":"Caltrans's formal way for a contractor, after award, to propose a cheaper way to do the work and share the savings.","ex":"It appears in section 4-1.07 of the Caltrans specifications used on 11-428704.","mod":15},
  {"term":"Valve box","abbr":"VB","cat":"Irrigation","def":"A plastic box with a lid set at grade over a valve, so it can be reached. Sizes like 10\" round, standard and jumbo.","ex":"Caltrans 11-428704 item 48: Replace Valve Box Cover Labels, 200 EA.","mod":6},
  {"term":"Variable","abbr":"VAR","also":"varies","cat":"Plans & drawings","def":"The value changes along the length, like a variable width planting strip.","mod":4},
  {"term":"Variable cost","abbr":"","cat":"Money & estimating","def":"A cost that changes with the amount of work, like material and labor.","mod":10},
  {"term":"Verify in field","abbr":"VIF","also":"field verify; FV","cat":"Plans & drawings","def":"Check this dimension or condition on site before building or ordering.","mod":4},
  {"term":"Vibratory plow","abbr":"","also":"pipe puller","cat":"Irrigation","def":"A machine that pulls pipe or wire into the ground without an open trench.","mod":9},
  {"term":"Volt","abbr":"V","also":"VAC","cat":"Units & measurement","def":"The unit of electrical pressure. Irrigation valve solenoids typically run on 24 VAC from the controller.","mod":6},
  {"term":"Waiver of subrogation","abbr":"","cat":"Licensing, insurance & bonds","def":"Your insurer agrees not to sue the GC or owner to recover money it paid on a claim. Needs an endorsement on your policy.","mod":2},
  {"term":"Walk the job","abbr":"","cat":"Construction phrases & jargon","def":"Field phrase for visiting the site before you bid, to see access, soil, slopes and existing conditions.","mod":12},
  {"term":"Walk-away price","abbr":"","also":"floor price","cat":"Money & estimating","def":"The lowest price you'll bid: cost plus overhead plus your minimum profit.","mod":10},
  {"term":"Warning tape","abbr":"","cat":"Irrigation","def":"Colored tape laid above a pipe in the trench to warn future diggers.","mod":6},
  {"term":"Warranty","abbr":"","also":"guarantee","cat":"Bidding & contracts","def":"Your promise to fix work or replace failed plants for a set time after acceptance. The specs set the length.","mod":13},
  {"term":"Warranty period","abbr":"","also":"guarantee period","cat":"Specifications","def":"How long your warranty lasts. Plant warranties often differ from irrigation warranties, so read both.","mod":16},
  {"term":"Waste factor","abbr":"","also":"waste","cat":"Money & estimating","def":"Extra quantity added for cutting, breakage and set lengths. Keep it separate from the net quantity so you can see it.","mod":6},
  {"term":"Water district","abbr":"","also":"water agency","cat":"Agencies & organizations","def":"The local agency that sells water and sets meter and backflow rules, like Otay Water District, Sweetwater Authority or the City of San Diego Public Utilities.","mod":6},
  {"term":"Water hammer","abbr":"","cat":"Irrigation","def":"A pressure surge when water flow stops suddenly, like a valve closing fast. It can break pipe and fittings.","mod":6},
  {"term":"Water meter","abbr":"","also":"meter","cat":"Irrigation","def":"The water agency's device that measures water use. A dedicated irrigation meter is often required on commercial sites.","ex":"Caltrans 11-431064 item 67: Water Meter Charges, LS.","mod":6},
  {"term":"Water pollution control plans","abbr":"WPC","cat":"Plans & drawings","def":"Caltrans sheets showing temporary storm water BMPs.","ex":"Caltrans 11-428704: WPC-1 to WPC-7 and WPCQ-1.","mod":4},
  {"term":"Water Pollution Control Program","abbr":"WPCP","cat":"Public works & compliance","def":"Caltrans's simpler storm water plan for jobs that don't need a full SWPPP, usually smaller sites.","ex":"Caltrans 11-422004 item 9: Prepare Water Pollution Control Program, LS.","mod":7},
  {"term":"Water truck","abbr":"","cat":"Grading, demo & erosion control","def":"A truck that sprays water for dust control and compaction.","mod":9},
  {"term":"Watering basin","abbr":"","also":"basin; berm","cat":"Planting & soil","def":"A ring of soil around a plant that holds water at the roots.","ex":"Caltrans 11-428704 plant legend: 60-inch diameter basin unless planted in a groundcover area.","mod":7},
  {"term":"Watt","abbr":"W","cat":"Units & measurement","def":"The unit of electrical power. Lighting transformers are sized by the total watts of the fixtures.","mod":7},
  {"term":"Weather day","abbr":"","also":"rain day","cat":"Construction phrases & jargon","def":"A day lost to weather. The contract says whether you get extra time for it.","mod":16},
  {"term":"Weed abatement","abbr":"","also":"weed control","cat":"Planting & soil","def":"Removing or killing weeds by hand, machine or herbicide.","mod":7},
  {"term":"Weed germination","abbr":"W Germ","also":"grow and kill","cat":"Planting & soil","def":"Watering a planting area to sprout weeds, then killing them, before planting.","ex":"Caltrans 11-428704 item 21: Weed Germination, 7,020 SQYD.","mod":7},
  {"term":"Whitebook","abbr":"","also":"City of San Diego Standard Specifications","cat":"Specifications","def":"The City of San Diego's supplement to the Greenbook. On City jobs it governs over the Greenbook.","mod":5},
  {"term":"Wildlife and nesting bird survey","abbr":"","also":"nesting bird survey","cat":"Public works & compliance","def":"A check by a biologist for active bird nests before clearing plants, often required during nesting season. If a nest is found, work near it can stop until the birds leave.","mod":12},
  {"term":"Wire mesh","abbr":"WWF","also":"welded wire fabric","cat":"Hardscape & site work","def":"A grid of steel wire set in concrete flatwork.","mod":7},
  {"term":"Wire splice","abbr":"","also":"waterproof connector","cat":"Irrigation","def":"A connection of two wires sealed against water, required for every buried splice.","mod":6},
  {"term":"Wood mulch","abbr":"","also":"wood chip mulch; bark mulch","cat":"Planting & soil","def":"Mulch made of chipped wood or bark, usually priced by the CY at a set depth.","ex":"Caltrans 11-428704 item 31: Wood Mulch, 190 CY.","mod":7},
  {"term":"Work in progress report","abbr":"WIP","also":"WIP schedule","cat":"Money & estimating","def":"A report of every open job: contract amount, cost to date, percent complete, billed to date and expected profit. Sureties and banks ask for it.","mod":16},
  {"term":"Workers' compensation","abbr":"WC","also":"workers' comp","cat":"Licensing, insurance & bonds","def":"Insurance that pays medical care and lost wages for injured employees. Required for any California employer with employees.","mod":2},
  {"term":"Working day","abbr":"WDAY","cat":"Bidding & contracts","def":"A day work can be done that counts toward contract time. Weekends, holidays and bad weather days usually don't count.","ex":"Caltrans 11-428704 item 2: Time-Related Overhead, 120 WDAY.","mod":3},
  {"term":"Working pressure","abbr":"","also":"dynamic pressure","cat":"Irrigation","def":"Water pressure while water is flowing. It's lower than static pressure.","mod":6},
  {"term":"WUCOLS","abbr":"WUCOLS","also":"Water Use Classification of Landscape Species","cat":"Planting & soil","def":"A guide that rates how much water each plant needs (very low, low, moderate, high) by region. MWELO water budgets use it.","mod":5},
  {"term":"Zone","abbr":"","also":"station; circuit","cat":"Irrigation","def":"A group of heads or drip run by one valve at the same time.","mod":6}
];
